{
  "name": "VocaMaster AI",
  "description": "A smart vocabulary testing platform that simulates daily curriculum from Google Sheets using Gemini AI. Features student self-testing, instant feedback, and a teacher dashboard."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Question {
  id: number;
  word: string;
  options: string[];
  correctAnswerIndex: number;
}

export interface QuizResult {
  studentName: string;
  date: string;
  score: number;
  totalQuestions: number;
  timeTakenSeconds: number;
  timestamp: string; // ISO string
}

export enum AppView {
  LANDING = 'LANDING',
  QUIZ = 'QUIZ',
  RESULT = 'RESULT',
  TEACHER_LOGIN = 'TEACHER_LOGIN',
  TEACHER_DASHBOARD = 'TEACHER_DASHBOARD',
}

export interface UserSession {
  name: string;
  date: string; // YYYY-MM-DD
}

import { GoogleGenAI, Type } from "@google/genai";
import { Question } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateQuizQuestions = async (date: string): Promise<Question[]> => {
  const model = "gemini-3-flash-preview";

  // Simulate pulling from a "Google Sheet" by using the date as a seed context.
  const prompt = `
    Generate a vocabulary test for students based on the curriculum for the date: ${date}.
    Create exactly 50 multiple-choice questions.

    For each question:
    1. Select a distinct English vocabulary word suitable for intermediate learners (CEFR B1/B2).
    2. Provide 4 Korean meanings as options.
    3. Only ONE option should be correct.
    4. The other 3 options should be plausible but incorrect meanings.

    Return the data strictly as a JSON array.
  `;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.INTEGER },
              word: { type: Type.STRING, description: "The English word" },
              options: { 
                type: Type.ARRAY, 
                items: { type: Type.STRING },
                description: "Array of 4 Korean definitions" 
              },
              correctAnswerIndex: { type: Type.INTEGER, description: "Index (0-3) of the correct option" }
            },
            required: ["id", "word", "options", "correctAnswerIndex"],
            propertyOrdering: ["id", "word", "options", "correctAnswerIndex"]
          },
        },
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from Gemini");

    const data = JSON.parse(text) as Question[];
    return data;

  } catch (error) {
    console.error("Error generating quiz:", error);
    // Fallback or re-throw
    throw error;
  }
};

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  fullWidth?: boolean;
}

const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  fullWidth = false, 
  className = '', 
  ...props 
}) => {
  const baseStyles = "px-4 py-2 rounded-lg font-medium transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed";

  const variants = {
    primary: "bg-indigo-600 text-white hover:bg-indigo-700 focus:ring-indigo-500 shadow-md hover:shadow-lg",
    secondary: "bg-white text-gray-700 border border-gray-300 hover:bg-gray-50 focus:ring-gray-500",
    danger: "bg-red-600 text-white hover:bg-red-700 focus:ring-red-500",
    ghost: "bg-transparent text-gray-600 hover:bg-gray-100 hover:text-gray-900",
  };

  return (
    <button
      className={`${baseStyles} ${variants[variant]} ${fullWidth ? 'w-full' : ''} ${className}`}
      {...props}
    >
      {children}
    </button>
  );
};

export default Button;

import React, { useState, useEffect } from 'react';
import { AppView, UserSession, QuizResult, Question } from './types';
import Landing from './views/Landing';
import Quiz from './views/Quiz';
import Result from './views/Result';
import TeacherDashboard from './views/TeacherDashboard';
import { generateQuizQuestions } from './services/geminiService';

// Mock storage key
const STORAGE_KEY = 'vocamaster_results';

function App() {
  const [currentView, setCurrentView] = useState<AppView>(AppView.LANDING);
  const [session, setSession] = useState<UserSession | null>(null);
  const [questions, setQuestions] = useState<Question[]>([]);
  const [lastResult, setLastResult] = useState<QuizResult | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [loadingMessage, setLoadingMessage] = useState('');

  // Save result to local storage for "Teacher" to see
  const saveResult = (result: QuizResult) => {
    const existing = localStorage.getItem(STORAGE_KEY);
    const results: QuizResult[] = existing ? JSON.parse(existing) : [];
    results.push(result);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(results));
    setLastResult(result);
  };

  const handleStartQuiz = async (name: string, date: string) => {
    setSession({ name, date });
    setIsLoading(true);
    setLoadingMessage(`Fetching '${date}' vocabulary list from Google Sheets (AI)...`);

    try {
      const generatedQuestions = await generateQuizQuestions(date);
      setQuestions(generatedQuestions);
      setCurrentView(AppView.QUIZ);
    } catch (error) {
      alert("Failed to load questions. Please try again. Make sure you have a valid API Key.");
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleQuizComplete = (score: number, total: number, timeSeconds: number) => {
    if (!session) return;

    const result: QuizResult = {
      studentName: session.name,
      date: session.date,
      score,
      totalQuestions: total,
      timeTakenSeconds: timeSeconds,
      timestamp: new Date().toISOString(),
    };

    saveResult(result);
    setCurrentView(AppView.RESULT);
  };

  const handleLogout = () => {
    setSession(null);
    setQuestions([]);
    setLastResult(null);
    setCurrentView(AppView.LANDING);
  };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 font-sans">
      <header className="bg-white shadow-sm border-b border-gray-200 sticky top-0 z-10">
        <div className="max-w-4xl mx-auto px-4 py-4 flex justify-between items-center">
          <div 
            className="flex items-center gap-2 cursor-pointer" 
            onClick={() => setCurrentView(AppView.LANDING)}
          >
            <div className="bg-indigo-600 text-white p-2 rounded-lg">
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                <path strokeLinecap="round" strokeLinejoin="round" d="M12 6.042A8.967 8.967 0 006 3.75c-1.052 0-2.062.18-3 .512v14.25A8.987 8.987 0 016 18c2.305 0 4.408.867 6 2.292m0-14.25a8.966 8.966 0 016-2.292c1.052 0 2.062.18 3 .512v14.25A8.987 8.987 0 0018 18a8.967 8.967 0 00-6 2.292m0-14.25v14.25" />
              </svg>
            </div>
            <h1 className="text-xl font-bold text-gray-800 tracking-tight">VocaMaster</h1>
          </div>

          {currentView === AppView.LANDING && (
             <button 
               onClick={() => setCurrentView(AppView.TEACHER_LOGIN)}
               className="text-sm text-gray-500 hover:text-indigo-600 font-medium transition-colors"
             >
               Teacher Access
             </button>
          )}
          {currentView === AppView.TEACHER_DASHBOARD && (
             <button 
               onClick={handleLogout}
               className="text-sm text-gray-500 hover:text-red-600 font-medium transition-colors"
             >
               Logout
             </button>
          )}
        </div>
      </header>

      <main className="max-w-4xl mx-auto px-4 py-8">
        {isLoading ? (
          <div className="flex flex-col items-center justify-center h-96 animate-pop">
             <div className="w-16 h-16 border-4 border-indigo-200 border-t-indigo-600 rounded-full animate-spin mb-6"></div>
             <p className="text-lg text-gray-600 font-medium">{loadingMessage}</p>
             <p className="text-sm text-gray-400 mt-2">Connecting to Knowledge Base...</p>
          </div>
        ) : (
          <>
            {currentView === AppView.LANDING && (
              <Landing onStart={handleStartQuiz} />
            )}

            {currentView === AppView.QUIZ && session && (
              <Quiz 
                questions={questions} 
                onComplete={handleQuizComplete} 
              />
            )}

            {currentView === AppView.RESULT && lastResult && (
              <Result 
                result={lastResult} 
                onHome={handleLogout} 
              />
            )}

            {currentView === AppView.TEACHER_LOGIN && (
              <div className="max-w-md mx-auto bg-white p-8 rounded-2xl shadow-lg border border-gray-100 animate-pop">
                <h2 className="text-2xl font-bold mb-6 text-center">Teacher Login</h2>
                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Access Code</label>
                    <input 
                      type="password" 
                      className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
                      placeholder="Enter code (any code works for demo)"
                    />
                  </div>
                  <button 
                    onClick={() => setCurrentView(AppView.TEACHER_DASHBOARD)}
                    className="w-full bg-gray-900 text-white py-2 rounded-lg hover:bg-black transition-colors"
                  >
                    Enter Dashboard
                  </button>
                  <button 
                    onClick={() => setCurrentView(AppView.LANDING)}
                    className="w-full text-gray-500 py-2 text-sm hover:text-gray-700"
                  >
                    Cancel
                  </button>
                </div>
              </div>
            )}

            {currentView === AppView.TEACHER_DASHBOARD && (
              <TeacherDashboard />
            )}
          </>
        )}
      </main>
    </div>
  );
}

export default App;

import React, { useState } from 'react';
import Button from '../components/Button';

interface LandingProps {
  onStart: (name: string, date: string) => void;
}

const Landing: React.FC<LandingProps> = ({ onStart }) => {
  const [name, setName] = useState('');
  // Default to today's date formatted as YYYY-MM-DD
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (name.trim() && date) {
      onStart(name.trim(), date);
    }
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-[60vh] animate-pop">
      <div className="w-full max-w-md bg-white rounded-2xl shadow-xl overflow-hidden border border-indigo-50">
        <div className="bg-indigo-600 p-8 text-center">
          <h2 className="text-3xl font-bold text-white mb-2">Daily Vocab Test</h2>
          <p className="text-indigo-100">Enter your details to retrieve today's word list.</p>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6">
          <div>
            <label htmlFor="date" className="block text-sm font-semibold text-gray-700 mb-2">
              Test Date (Sheet Tab)
            </label>
            <input
              type="date"
              id="date"
              required
              value={date}
              onChange={(e) => setDate(e.target.value)}
              className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
            />
            <p className="text-xs text-gray-500 mt-1">
              *The system will fetch 50 random words assigned to this date.
            </p>
          </div>

          <div>
            <label htmlFor="name" className="block text-sm font-semibold text-gray-700 mb-2">
              Student Name
            </label>
            <input
              type="text"
              id="name"
              required
              placeholder="Ex: John Doe"
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
            />
          </div>

          <Button type="submit" fullWidth className="text-lg py-3 shadow-indigo-200">
            Start Test
          </Button>
        </form>
      </div>

      <div className="mt-8 text-center text-sm text-gray-500 max-w-sm">
        <p>This program uses AI to simulate a database connection. Selecting a date will generate a unique set of words for that day.</p>
      </div>
    </div>
  );
};

export default Landing;

import React, { useState, useEffect, useCallback } from 'react';
import { Question } from '../types';
import Button from '../components/Button';

interface QuizProps {
  questions: Question[];
  onComplete: (score: number, total: number, timeSeconds: number) => void;
}

const Quiz: React.FC<QuizProps> = ({ questions, onComplete }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [selectedOption, setSelectedOption] = useState<number | null>(null);
  const [score, setScore] = useState(0);
  const [isAnswered, setIsAnswered] = useState(false);
  const [startTime] = useState(Date.now());
  const [currentTime, setCurrentTime] = useState(0); // seconds
  const [shake, setShake] = useState(false);

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentTime(Math.floor((Date.now() - startTime) / 1000));
    }, 1000);
    return () => clearInterval(timer);
  }, [startTime]);

  const currentQuestion = questions[currentIndex];

  const handleOptionClick = (optionIndex: number) => {
    if (isAnswered) return;

    setSelectedOption(optionIndex);
    setIsAnswered(true);

    const isCorrect = optionIndex === currentQuestion.correctAnswerIndex;

    if (isCorrect) {
      setScore(prev => prev + 1);
    } else {
      // Trigger shake animation for wrong answer
      setShake(true);
      setTimeout(() => setShake(false), 500);
    }

    // Auto advance after 1.5 seconds
    setTimeout(() => {
      if (currentIndex < questions.length - 1) {
        setCurrentIndex(prev => prev + 1);
        setSelectedOption(null);
        setIsAnswered(false);
      } else {
        const finalTime = Math.floor((Date.now() - startTime) / 1000);
        onComplete(isCorrect ? score + 1 : score, questions.length, finalTime);
      }
    }, 1500);
  };

  const getButtonClass = (index: number) => {
    if (!isAnswered) return "bg-white hover:bg-gray-50 border-gray-200 text-gray-700";

    // Correct Answer (always show green if answered)
    if (index === currentQuestion.correctAnswerIndex) {
      return "bg-green-100 border-green-500 text-green-800 ring-1 ring-green-500 font-semibold";
    }

    // Wrong selection
    if (index === selectedOption && index !== currentQuestion.correctAnswerIndex) {
      return "bg-red-100 border-red-500 text-red-800 ring-1 ring-red-500";
    }

    // Others
    return "bg-gray-50 border-gray-200 text-gray-400 opacity-60";
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
  };

  const progress = ((currentIndex + 1) / questions.length) * 100;

  return (
    <div className="max-w-2xl mx-auto animate-pop">
      {/* Top Bar */}
      <div className="flex justify-between items-center mb-6 bg-white p-4 rounded-xl shadow-sm border border-gray-100">
        <div className="flex flex-col">
          <span className="text-xs font-semibold text-gray-400 uppercase tracking-wide">Progress</span>
          <span className="text-xl font-bold text-indigo-600">{currentIndex + 1} <span className="text-gray-400 text-base font-medium">/ {questions.length}</span></span>
        </div>
        <div className="flex flex-col items-end">
          <span className="text-xs font-semibold text-gray-400 uppercase tracking-wide">Time</span>
          <span className="text-xl font-mono font-bold text-gray-700">{formatTime(currentTime)}</span>
        </div>
      </div>

      {/* Progress Bar */}
      <div className="w-full bg-gray-200 rounded-full h-2.5 mb-8">
        <div 
          className="bg-indigo-600 h-2.5 rounded-full transition-all duration-300 ease-out" 
          style={{ width: `${progress}%` }}
        ></div>
      </div>

      {/* Question Card */}
      <div className={`bg-white rounded-2xl shadow-xl overflow-hidden border border-gray-100 transition-transform duration-200 ${shake ? 'animate-shake' : ''}`}>
        <div className="bg-gradient-to-r from-indigo-600 to-indigo-500 p-10 text-center">
          <h2 className="text-4xl md:text-5xl font-bold text-white tracking-tight drop-shadow-sm">
            {currentQuestion.word}
          </h2>
          <p className="text-indigo-100 mt-2 text-sm font-medium">Choose the correct meaning</p>
        </div>

        <div className="p-6 grid gap-4">
          {currentQuestion.options.map((option, idx) => (
            <button
              key={idx}
              disabled={isAnswered}
              onClick={() => handleOptionClick(idx)}
              className={`w-full text-left px-6 py-4 rounded-xl border-2 transition-all duration-200 flex items-center justify-between group ${getButtonClass(idx)}`}
            >
              <span className="text-lg">{option}</span>
              {isAnswered && idx === currentQuestion.correctAnswerIndex && (
                 <svg className="w-6 h-6 text-green-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                   <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                 </svg>
              )}
              {isAnswered && idx === selectedOption && idx !== currentQuestion.correctAnswerIndex && (
                 <svg className="w-6 h-6 text-red-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                   <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                 </svg>
              )}
            </button>
          ))}
        </div>
      </div>

      <div className="mt-4 text-center">
         <span className="text-sm text-gray-400">Question {currentIndex + 1} of {questions.length}</span>
      </div>
    </div>
  );
};

export default Quiz;

import React from 'react';
import { QuizResult } from '../types';
import Button from '../components/Button';

interface ResultProps {
  result: QuizResult;
  onHome: () => void;
}

const Result: React.FC<ResultProps> = ({ result, onHome }) => {
  const percentage = Math.round((result.score / result.totalQuestions) * 100);

  let gradeColor = 'text-red-500';
  let message = 'Keep practicing!';

  if (percentage >= 90) {
    gradeColor = 'text-green-500';
    message = 'Excellent work!';
  } else if (percentage >= 70) {
    gradeColor = 'text-blue-500';
    message = 'Good job!';
  } else if (percentage >= 50) {
    gradeColor = 'text-yellow-500';
    message = 'You can do better!';
  }

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}m ${s}s`;
  };

  return (
    <div className="flex flex-col items-center justify-center animate-pop py-8">
      <div className="bg-white rounded-3xl shadow-xl overflow-hidden max-w-lg w-full border border-gray-100">
        <div className="bg-gray-900 text-white p-8 text-center relative overflow-hidden">
          {/* Decorative circles */}
          <div className="absolute top-0 left-0 -translate-x-1/2 -translate-y-1/2 w-32 h-32 bg-white opacity-10 rounded-full"></div>
          <div className="absolute bottom-0 right-0 translate-x-1/2 translate-y-1/2 w-48 h-48 bg-indigo-500 opacity-20 rounded-full"></div>

          <h2 className="text-3xl font-bold relative z-10 mb-2">{result.studentName}</h2>
          <p className="text-gray-400 text-sm relative z-10">{result.date}</p>
        </div>

        <div className="p-8 text-center">
          <div className="mb-2 text-gray-500 text-sm font-semibold uppercase tracking-wider">Your Score</div>
          <div className={`text-6xl font-extrabold mb-2 ${gradeColor}`}>
            {result.score} <span className="text-2xl text-gray-400 font-normal">/ {result.totalQuestions}</span>
          </div>
          <p className="text-gray-600 font-medium text-lg mb-8">{message}</p>

          <div className="grid grid-cols-2 gap-4 mb-8">
            <div className="bg-gray-50 p-4 rounded-xl">
              <div className="text-gray-400 text-xs uppercase font-bold mb-1">Time Taken</div>
              <div className="text-xl font-bold text-gray-800">{formatTime(result.timeTakenSeconds)}</div>
            </div>
            <div className="bg-gray-50 p-4 rounded-xl">
              <div className="text-gray-400 text-xs uppercase font-bold mb-1">Accuracy</div>
              <div className="text-xl font-bold text-gray-800">{percentage}%</div>
            </div>
          </div>

          <Button onClick={onHome} fullWidth size="lg">
            Back to Home
          </Button>
        </div>
      </div>
    </div>
  );
};

export default Result;

import React, { useEffect, useState } from 'react';
import { QuizResult } from '../types';

const STORAGE_KEY = 'vocamaster_results';

const TeacherDashboard: React.FC = () => {
  const [results, setResults] = useState<QuizResult[]>([]);

  useEffect(() => {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored) {
      try {
        const parsed = JSON.parse(stored) as QuizResult[];
        // Sort by timestamp descending
        parsed.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
        setResults(parsed);
      } catch (e) {
        console.error("Failed to parse results");
      }
    }
  }, []);

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
  };

  const formatDate = (isoString: string) => {
    return new Date(isoString).toLocaleString();
  };

  const clearData = () => {
    if (confirm("Are you sure you want to clear all student records?")) {
      localStorage.removeItem(STORAGE_KEY);
      setResults([]);
    }
  };

  return (
    <div className="animate-pop">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-gray-800">Student Results Dashboard</h2>
        <button 
          onClick={clearData}
          className="text-red-600 hover:text-red-800 text-sm font-medium hover:underline"
        >
          Clear All Data
        </button>
      </div>

      <div className="bg-white rounded-xl shadow-md border border-gray-200 overflow-hidden">
        {results.length === 0 ? (
          <div className="p-12 text-center text-gray-500">
            <svg className="w-16 h-16 mx-auto text-gray-300 mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01" />
            </svg>
            <p>No tests taken yet.</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-gray-50 border-b border-gray-200">
                  <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Date (Sheet Tab)</th>
                  <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Student Name</th>
                  <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Score</th>
                  <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Time Taken</th>
                  <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Timestamp</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {results.map((r, idx) => (
                  <tr key={idx} className="hover:bg-gray-50 transition-colors">
                    <td className="px-6 py-4 text-sm text-gray-900 font-medium">{r.date}</td>
                    <td className="px-6 py-4 text-sm text-gray-700">{r.studentName}</td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
                        (r.score / r.totalQuestions) > 0.8 ? 'bg-green-100 text-green-800' : 
                        (r.score / r.totalQuestions) > 0.5 ? 'bg-yellow-100 text-yellow-800' : 
                        'bg-red-100 text-red-800'
                      }`}>
                        {r.score} / {r.totalQuestions}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-500 font-mono">{formatTime(r.timeTakenSeconds)}</td>
                    <td className="px-6 py-4 text-sm text-gray-400">{formatDate(r.timestamp)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
};

