import { GoogleGenAI, Type } from "@google/genai";
import { Question } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateQuizQuestions = async (date: string, customWords?: string[]): Promise<Question[]> => {
  const model = "gemini-3-flash-preview";

  let prompt = "";

  if (customWords && customWords.length > 0) {
    // Mode 1: Use provided words
    prompt = `
      Create a vocabulary test using EXACTLY the following English words: ${JSON.stringify(customWords)}.
      Total questions should match the number of words provided (up to 50).

      For each question:
      1. Use the provided English word.
      2. Provide 4 Korean meanings as options.
      3. Only ONE option should be correct.
      4. The other 3 options should be plausible but incorrect meanings.

      Return the data strictly as a JSON array.
    `;
  } else {
    // Mode 2: AI Simulation (Fall back)
    prompt = `
      Generate a vocabulary test for students based on the curriculum for the date: ${date}.
      Create exactly 50 multiple-choice questions.

      For each question:
      1. Select a distinct English vocabulary word suitable for intermediate learners (CEFR B1/B2).
      2. Provide 4 Korean meanings as options.
      3. Only ONE option should be correct.
      4. The other 3 options should be plausible but incorrect meanings.

      Return the data strictly as a JSON array.
    `;
  }

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.INTEGER },
              word: { type: Type.STRING, description: "The English word" },
              options: { 
                type: Type.ARRAY, 
                items: { type: Type.STRING },
                description: "Array of 4 Korean definitions" 
              },
              correctAnswerIndex: { type: Type.INTEGER, description: "Index (0-3) of the correct option" }
            },
            required: ["id", "word", "options", "correctAnswerIndex"],
            propertyOrdering: ["id", "word", "options", "correctAnswerIndex"]
          },
        },
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from Gemini");

    const data = JSON.parse(text) as Question[];
    return data;

  } catch (error) {
    console.error("Error generating quiz:", error);
    // Fallback or re-throw
    throw error;
  }
};

