// Helper to parse CSV line correctly handling quotes
const parseCSVLine = (line: string): string[] => {
  const result = [];
  let start = 0;
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    if (line[i] === '"') {
      inQuotes = !inQuotes;
    } else if (line[i] === ',' && !inQuotes) {
      result.push(line.substring(start, i).replace(/^"|"$/g, '').replace(/""/g, '"').trim());
      start = i + 1;
    }
  }
  result.push(line.substring(start).replace(/^"|"$/g, '').replace(/""/g, '"').trim());
  return result;
};

export const fetchWordsFromSheet = async (sheetId: string, tabName: string): Promise<SheetWord[]> => {
  // Use Google Visualization API to get CSV of a specific sheet tab
  // Note: The sheet must be "Published to the Web" for this to work without OAuth
  const url = `https://docs.google.com/spreadsheets/d/${sheetId}/gviz/tq?tqx=out:csv&sheet=${encodeURIComponent(tabName)}`;

  try {
    const response = await fetch(url);

    if (!response.ok) {
      if (response.status === 404) {
        throw new Error(`Sheet not found. Check ID or Tab Name: ${tabName}`);
      }
      throw new Error(`Failed to fetch sheet. Status: ${response.status}`);
    }

    const text = await response.text();

    // Basic CSV parsing
    const lines = text.split('\n');
    const words: SheetWord[] = [];

    // Skip header row if it looks like "Word,Meaning" or similar, otherwise process all
    // We assume Column A is English Word, Column B is Korean Meaning
    const startIdx = 0; 

    for (let i = startIdx; i < lines.length; i++) {
      const line = lines[i].trim();
      if (!line) continue;

      const cols = parseCSVLine(line);

      // We need at least 2 columns: Word and Meaning
      if (cols.length >= 2) {
        const word = cols[0];
        const meaning = cols[1];

        // Simple validation to skip potential header rows if user didn't specify
        if (word.toLowerCase() === 'word' || word.toLowerCase() === 'english') continue;

        if (word && meaning) {
          words.push({ word, meaning });
        }
      }
    }

    if (words.length === 0) {
      throw new Error("Found the sheet tab, but could not parse any words. Ensure Col A is Word and Col B is Meaning.");
    }

    return words;

  } catch (error) {
    console.error("Sheet Fetch Error:", error);
    throw error;
  }
};

import { GoogleGenAI, Type } from "@google/genai";
import { Question, SheetWord } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateQuizQuestions = async (date: string, sheetWords?: SheetWord[]): Promise<Question[]> => {
  const model = "gemini-3-flash-preview";
  let prompt = "";

  if (sheetWords && sheetWords.length > 0) {
    // Mode 1: Real Data from Sheet
    // We pass the word and the correct meaning. Gemini needs to generate 3 wrong options.
    const limitedWords = sheetWords.slice(0, 50); // Cap at 50 to avoid token limits if list is huge

    prompt = `
      I have a vocabulary list for a test.
      SOURCE DATA: ${JSON.stringify(limitedWords)}

      Task: Create a multiple-choice test based strictly on this source data.

      For each item in the source data:
      1. Use the 'word' as the question.
      2. Use the 'meaning' as the Correct Answer.
      3. Generate 3 other INCORRECT Korean meanings (distractors) that are plausible but definitely wrong for this word.
      4. Randomly shuffle the position of the correct answer among the 4 options.
      5. 'correctAnswerIndex' must point to the correct meaning in the 'options' array.

      Return the result as a JSON array of Question objects.
    `;
  } else {
    // Mode 2: Fallback (AI Simulation if no sheet data found/provided)
    prompt = `
      Generate a vocabulary test for students based on a simulated curriculum for date: ${date}.
      Create exactly 50 multiple-choice questions.

      For each question:
      1. Select a distinct English vocabulary word (CEFR B1/B2).
      2. Provide 4 Korean meanings as options.
      3. Only ONE option should be correct.
      4. The other 3 options should be plausible but incorrect meanings.

      Return the data strictly as a JSON array.
    `;
  }

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.INTEGER },
              word: { type: Type.STRING },
              options: { 
                type: Type.ARRAY, 
                items: { type: Type.STRING },
              },
              correctAnswerIndex: { type: Type.INTEGER }
            },
            required: ["id", "word", "options", "correctAnswerIndex"],
            propertyOrdering: ["id", "word", "options", "correctAnswerIndex"]
          },
        },
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from Gemini");

    const data = JSON.parse(text) as Question[];
    return data;

  } catch (error) {
    console.error("Error generating quiz:", error);
    throw error;
  }
};

import React, { useEffect, useState } from 'react';
