  const handleCopyLink = () => {
    const origin = window.location.origin + window.location.pathname;
    // Include both sheet_id and script_url in the link if available
    let link = `${origin}?sheet_id=${sheetId}`;

    // We base64 encode the script URL to avoid URL parsing issues with parameters
    if (scriptUrl) {
      const encodedUrl = btoa(scriptUrl);
      link += `&script=${encodedUrl}`;
    }

    navigator.clipboard.writeText(link);
    setIsCopied(true);
    setTimeout(() => setIsCopied(false), 2000);
  };

  const formatTime = (seconds: number) => {
