            <ol className="list-decimal list-inside mt-2 space-y-1">
              <li>In your Google Sheet, go to <strong>Extensions {'>'} Apps Script</strong>.</li>
              <li>Paste the backend script code (found in documentation).</li>
              <li>Click <strong>Deploy {'>'} New deployment</strong>.</li>
              <li>Select <strong>Web app</strong>, set "Who has access" to <strong>"Anyone"</strong>.</li>
              <li>Copy the Web App URL and paste it above.</li>
            </ol>
          </div>
        </div>
      </div>

      {/* Results Section */}
      <div>
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-2xl font-bold text-gray-800">Student Results (Local Only)</h2>
          <button 
            onClick={clearData}
            className="text-red-600 hover:text-red-800 text-sm font-medium hover:underline"
          >
            Clear Data
          </button>
        </div>

        <div className="bg-amber-50 border-l-4 border-amber-500 p-4 mb-6">
          <div className="flex">
            <div className="flex-shrink-0">
              <svg className="h-5 w-5 text-amber-400" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
              </svg>
            </div>
            <div className="ml-3">
              <p className="text-sm text-amber-700">
                <strong>Note:</strong> This table only shows results from <em>this device</em>. 
                If you configured the <strong>Apps Script URL</strong> above, check your Google Sheet "Results" tab for all student submissions.
              </p>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-xl shadow-md border border-gray-200 overflow-hidden">
          {results.length === 0 ? (
            <div className="p-12 text-center text-gray-500">
              <p>No tests taken on this device yet.</p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-gray-50 border-b border-gray-200">
                    <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Tab Name</th>
                    <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Student Name</th>
                    <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Score</th>
                    <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Time Taken</th>
                    <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Timestamp</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {results.map((r, idx) => (
                    <tr key={idx} className="hover:bg-gray-50 transition-colors">
                      <td className="px-6 py-4 text-sm text-gray-900 font-medium">{r.date}</td>
                      <td className="px-6 py-4 text-sm text-gray-700">{r.studentName}</td>
                      <td className="px-6 py-4">
                        <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
                          (r.score / r.totalQuestions) > 0.8 ? 'bg-green-100 text-green-800' : 
                          (r.score / r.totalQuestions) > 0.5 ? 'bg-yellow-100 text-yellow-800' : 
                          'bg-red-100 text-red-800'
                        }`}>
                          {r.score} / {r.totalQuestions}
                        </span>
                      </td>
                      <td className="px-6 py-4 text-sm text-gray-500 font-mono">{formatTime(r.timeTakenSeconds)}</td>
                      <td className="px-6 py-4 text-sm text-gray-400">{formatDate(r.timestamp)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default TeacherDashboard;

import React, { useState, useEffect } from 'react';
import Button from '../components/Button';
import { AppView } from '../types';
import { fetchSheetTabs } from '../services/sheetService';

interface LandingProps {
  onStart: (name: string, date: string) => void;
  onChangeView: (view: AppView) => void;
}

const Landing: React.FC<LandingProps> = ({ onStart, onChangeView }) => {
  const [name, setName] = useState('');
  const [tabName, setTabName] = useState('');
  const [hasSheetId, setHasSheetId] = useState(false);
  const [sheetId, setSheetId] = useState('');

  // State for dynamic tab loading
  const [availableTabs, setAvailableTabs] = useState<string[]>([]);
  const [isLoadingTabs, setIsLoadingTabs] = useState(false);
  const [useDropdown, setUseDropdown] = useState(true);
  const [manualMode, setManualMode] = useState<'date' | 'text'>('date');

  useEffect(() => {
    const SHEET_KEY = 'vocamaster_sheet_id';
    const SCRIPT_KEY = 'vocamaster_script_url';

    // 1. Check URL parameters
    const params = new URLSearchParams(window.location.search);
    const urlSheetId = params.get('sheet_id');
    const urlScript = params.get('script');

    if (urlSheetId) {
      localStorage.setItem(SHEET_KEY, urlSheetId);
      setSheetId(urlSheetId);
      setHasSheetId(true);
      loadTabs(urlSheetId);
    } else {
      const storedSheetId = localStorage.getItem(SHEET_KEY);
      if (storedSheetId) {
        setSheetId(storedSheetId);
        setHasSheetId(true);
        loadTabs(storedSheetId);
      }
    }

    if (urlScript) {
      try {
        // Decode base64 script url
        const decoded = atob(urlScript);
        localStorage.setItem(SCRIPT_KEY, decoded);
      } catch (e) {
        console.error("Invalid script url param");
      }
    }

    // Clean URL if parameters existed
    if (urlSheetId || urlScript) {
       window.history.replaceState({}, document.title, window.location.pathname);
    }

  }, []);

  const loadTabs = async (id: string) => {
    setIsLoadingTabs(true);
    try {
      const tabs = await fetchSheetTabs(id);
      if (tabs.length > 0) {
        setAvailableTabs(tabs);
        setTabName(tabs[0]); // Default to first tab
        setUseDropdown(true);
      } else {
        // Fallback to manual input if API fails or returns no tabs
        setUseDropdown(false);
        setManualMode('date');
      }
    } catch (e) {
      console.error(e);
      setUseDropdown(false);
      setManualMode('date');
    } finally {
      setIsLoadingTabs(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (name.trim() && tabName.trim()) {
      onStart(name.trim(), tabName.trim());
    }
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-[60vh] animate-pop pb-10">
      <div className="w-full max-w-md bg-white rounded-2xl shadow-xl overflow-hidden border border-indigo-50">
        <div className="bg-indigo-600 p-8 text-center">
          <h2 className="text-3xl font-bold text-white mb-2">VocaMaster</h2>
          <p className="text-indigo-100">Teacher-Led Vocabulary Test</p>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6">
          {!hasSheetId && (
            <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4 flex items-start gap-3">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-yellow-600 flex-shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
              </svg>
              <div className="text-sm text-yellow-800">
                <p className="font-bold">Setup Required</p>
                <p>Teacher needs to set the <strong>Google Sheet ID</strong> in the dashboard first, or use the invite link provided by your teacher.</p>
              </div>
            </div>
          )}

          <div>
            <div className="flex justify-between items-center mb-2">
              <label htmlFor="tabName" className="block text-sm font-semibold text-gray-700">
                Select Test Date (Sheet Tab)
              </label>
              {!useDropdown && hasSheetId && !isLoadingTabs && (
                <div className="flex gap-2 text-xs">
                  <button 
                    type="button"
                    onClick={() => setManualMode(manualMode === 'date' ? 'text' : 'date')}
                    className="text-indigo-600 hover:text-indigo-800 underline"
                  >
                    Use {manualMode === 'date' ? 'Text Input' : 'Date Picker'}
                  </button>
                  <span className="text-gray-300">|</span>
                  <button 
                    type="button" 
                    onClick={() => loadTabs(sheetId)}
                    className="text-indigo-600 hover:text-indigo-800 underline"
                  >
                    Retry List
                  </button>
                </div>
              )}
            </div>

            {isLoadingTabs ? (
              <div className="w-full px-4 py-3 rounded-lg border border-gray-300 bg-gray-50 text-gray-500 text-sm flex items-center gap-2">
                <div className="w-4 h-4 border-2 border-gray-400 border-t-indigo-600 rounded-full animate-spin"></div>
                Loading tabs from sheet...
              </div>
            ) : useDropdown && availableTabs.length > 0 ? (
              <div className="relative">
                <select
                  id="tabName"
                  required
                  value={tabName}
                  onChange={(e) => setTabName(e.target.value)}
                  disabled={!hasSheetId}
                  className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all disabled:bg-gray-100 disabled:cursor-not-allowed appearance-none bg-white cursor-pointer"
                >
                  {availableTabs.map((tab) => (
                    <option key={tab} value={tab}>{tab}</option>
                  ))}
                </select>
                <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-4 text-gray-700">
                  <svg className="fill-current h-4 w-4" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path d="M9.293 12.95l.707.707L15.657 8l-1.414-1.414L10 10.828 5.757 6.586 4.343 8z"/></svg>
                </div>
              </div>
            ) : (
              <div className="relative">
                <input
                  type={manualMode}
                  id="tabName"
                  required
                  placeholder={manualMode === 'text' ? "Ex: Day1, 05-01, Week3..." : ""}
                  value={tabName}
                  onChange={(e) => setTabName(e.target.value)}
                  disabled={!hasSheetId}
                  className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all disabled:bg-gray-100 disabled:cursor-not-allowed"
                />
                {!isLoadingTabs && hasSheetId && (
                   <p className="text-xs text-orange-500 mt-1">
                     *Could not auto-load tabs. {manualMode === 'date' ? 'Select the date from calendar.' : 'Type the exact tab name.'}
                   </p>
                )}
              </div>
            )}
          </div>

          <div>
            <label htmlFor="name" className="block text-sm font-semibold text-gray-700 mb-2">
              Student Name
            </label>
            <input
              type="text"
              id="name"
              required
              placeholder="Ex: John Doe"
              value={name}
              onChange={(e) => setName(e.target.value)}
              disabled={!hasSheetId}
              className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all disabled:bg-gray-100 disabled:cursor-not-allowed"
            />
          </div>

          <Button type="submit" fullWidth disabled={!hasSheetId} className="text-lg py-3 shadow-indigo-200">
            Start Test
          </Button>
        </form>
      </div>

      <div className="mt-6 w-full max-w-md">
        <Button 
          variant="secondary" 
          fullWidth 
          onClick={() => onChangeView(AppView.INCORRECT_NOTE)}
          className="flex items-center justify-center gap-2"
        >
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5 text-red-500">
            <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3.75m9-.75a9 9 0 11-18 0 9 9 0 0118 0zm-9 3.75h.008v.008H12v-.008z" />
          </svg>
          Open Incorrect Answer Note
        </Button>
      </div>
    </div>
  );
};

export default Landing;

import React, { useState, useEffect } from 'react';
import { AppView, UserSession, QuizResult, Question, IncorrectWord } from './types';
import Landing from './views/Landing';
import Quiz from './views/Quiz';
import Result from './views/Result';
import TeacherDashboard from './views/TeacherDashboard';
import IncorrectNote from './views/IncorrectNote';
import { generateQuizQuestions } from './services/geminiService';
import { fetchWordsFromSheet, submitResultToSheet } from './services/sheetService';

const RESULT_STORAGE_KEY = 'vocamaster_results';
const INCORRECT_STORAGE_KEY = 'vocamaster_incorrect_notes';
const SHEET_ID_KEY = 'vocamaster_sheet_id';
const SCRIPT_URL_KEY = 'vocamaster_script_url';

function App() {
  const [currentView, setCurrentView] = useState<AppView>(AppView.LANDING);
  const [session, setSession] = useState<UserSession | null>(null);
  const [questions, setQuestions] = useState<Question[]>([]);
  const [lastResult, setLastResult] = useState<QuizResult | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [loadingMessage, setLoadingMessage] = useState('');
  const [submissionStatus, setSubmissionStatus] = useState<'idle' | 'submitting' | 'success' | 'error'>('idle');

  const [isReviewMode, setIsReviewMode] = useState(false);
  const [incorrectRecords, setIncorrectRecords] = useState<Record<string, IncorrectWord[]>>({});

  // Login State
  const [accessCode, setAccessCode] = useState('');
  const [loginError, setLoginError] = useState('');

  useEffect(() => {
    const stored = localStorage.getItem(INCORRECT_STORAGE_KEY);
    if (stored) {
      try {
        setIncorrectRecords(JSON.parse(stored));
      } catch (e) {
        console.error("Failed to load incorrect records");
      }
    }
  }, []);

  const saveResult = (result: QuizResult) => {
    // 1. Save locally
    const existing = localStorage.getItem(RESULT_STORAGE_KEY);
    const results: QuizResult[] = existing ? JSON.parse(existing) : [];
    results.push(result);
    localStorage.setItem(RESULT_STORAGE_KEY, JSON.stringify(results));
    setLastResult(result);

    // 2. Try to auto-submit to Sheet
    const scriptUrl = localStorage.getItem(SCRIPT_URL_KEY);
    if (scriptUrl) {
      setSubmissionStatus('submitting');
      submitResultToSheet(scriptUrl, result).then(success => {
        setSubmissionStatus(success ? 'success' : 'error');
      });
    } else {
      setSubmissionStatus('idle');
    }
  };

  const updateIncorrectWords = (studentName: string, quizQuestions: Question[], wrongQuestions: Question[]) => {
    const records = { ...incorrectRecords };
    let studentKey = Object.keys(records).find(k => k.toLowerCase() === studentName.toLowerCase().trim());

    if (!studentKey) {
      studentKey = studentName.trim();
      records[studentKey] = [];
    }

    const studentWords = records[studentKey];
    const now = new Date().toISOString();

    if (isReviewMode) {
      const wrongIds = new Set(wrongQuestions.map(q => q.id));
      const correctIds = quizQuestions.filter(q => !wrongIds.has(q.id)).map(q => q.id);

      records[studentKey] = studentWords.map(w => {
         if (correctIds.includes(w.question.id)) {
           return { ...w, wrongCount: w.wrongCount - 1 };
         }
         return w;
      }).filter(w => w.wrongCount > 0);

      records[studentKey] = records[studentKey].map(w => {
        if (wrongIds.has(w.question.id)) {
           return { ...w, wrongCount: w.wrongCount + 1, lastMissedDate: now };
        }
        return w;
      });

    } else {
      wrongQuestions.forEach(q => {
        const existingIndex = studentWords.findIndex(w => w.question.word === q.word);
        if (existingIndex >= 0) {
          studentWords[existingIndex].wrongCount += 1;
          studentWords[existingIndex].lastMissedDate = now;
          studentWords[existingIndex].question = q; 
        } else {
          studentWords.push({
            question: q,
            wrongCount: 1,
            lastMissedDate: now
          });
        }
      });
    }

    setIncorrectRecords(records);
    localStorage.setItem(INCORRECT_STORAGE_KEY, JSON.stringify(records));
  };

  const handleStartQuiz = async (name: string, tabName: string) => {
    setSession({ name, date: tabName });
    setIsLoading(true);
    setLoadingMessage(`Connecting to Google Sheet Tab: '${tabName}'...`);
    setIsReviewMode(false);
    setSubmissionStatus('idle');

    try {
      // 1. Get Sheet ID
      const sheetId = localStorage.getItem(SHEET_ID_KEY);
      if (!sheetId) {
        throw new Error("Teacher has not configured the Google Sheet ID yet.");
      }

      // 2. Fetch Words from Sheet
      const sheetWords = await fetchWordsFromSheet(sheetId, tabName);

      const count = Math.min(sheetWords.length, 50);
      setLoadingMessage(`Preparing test with ${count} random words from ${sheetWords.length} found...`);

      // 3. Generate Distractors via Gemini (it will shuffle and pick 50)
      const generatedQuestions = await generateQuizQuestions(tabName, sheetWords);

      setQuestions(generatedQuestions);
      setCurrentView(AppView.QUIZ);

    } catch (error: any) {
      alert(`Error: ${error.message}\n\nPlease check the Sheet ID and Tab Name. Ensure the sheet is 'Published to Web'.`);
      console.error(error);
      setSession(null);
    } finally {
      setIsLoading(false);
    }
  };

  const handleStartReview = (reviewQuestions: Question[], studentName?: string) => {
    if (studentName) {
      setSession({ name: studentName, date: 'Review' });
    }
    setQuestions(reviewQuestions);
    setIsReviewMode(true);
    setCurrentView(AppView.QUIZ);
  };

  const handleQuizComplete = (score: number, total: number, timeSeconds: number, wrongQuestions: Question[]) => {
    if (!session && !isReviewMode) return;

    const nameToUse = session?.name || "Unknown Student";

    updateIncorrectWords(nameToUse, questions, wrongQuestions);

    const result: QuizResult = {
      studentName: nameToUse,
      date: session?.date || "Review Mode",
      score,
      totalQuestions: total,
      timeTakenSeconds: timeSeconds,
      timestamp: new Date().toISOString(),
    };

    if (!isReviewMode) {
      saveResult(result);
    } else {
      setLastResult(result);
    }

    setCurrentView(AppView.RESULT);
  };

  const handleLogin = () => {
    if (accessCode === 'teacher') {
      setLoginError('');
      setAccessCode('');
      setCurrentView(AppView.TEACHER_DASHBOARD);
    } else {
      setLoginError('Invalid access code. Try "teacher".');
    }
  };

  const handleLogout = () => {
    setSession(null);
    setQuestions([]);
    setLastResult(null);
    setIsReviewMode(false);
    setCurrentView(AppView.LANDING);
    setAccessCode('');
    setLoginError('');
  };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 font-sans">
      <header className="bg-white shadow-sm border-b border-gray-200 sticky top-0 z-10">
        <div className="max-w-4xl mx-auto px-4 py-4 flex justify-between items-center">
          <div 
            className="flex items-center gap-2 cursor-pointer" 
            onClick={() => setCurrentView(AppView.LANDING)}
          >
            <div className="bg-indigo-600 text-white p-2 rounded-lg">
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                <path strokeLinecap="round" strokeLinejoin="round" d="M12 6.042A8.967 8.967 0 006 3.75c-1.052 0-2.062.18-3 .512v14.25A8.987 8.987 0 016 18c2.305 0 4.408.867 6 2.292m0-14.25a8.966 8.966 0 016-2.292c1.052 0 2.062.18 3 .512v14.25A8.987 8.987 0 0018 18a8.967 8.967 0 00-6 2.292m0-14.25v14.25" />
              </svg>
            </div>
            <h1 className="text-xl font-bold text-gray-800 tracking-tight">VocaMaster</h1>
          </div>

          {currentView === AppView.LANDING && (
             <div className="flex gap-4">
                <button 
                  onClick={() => setCurrentView(AppView.TEACHER_LOGIN)}
                  className="text-sm text-gray-500 hover:text-indigo-600 font-medium transition-colors"
                >
                  Teacher Access
                </button>
             </div>
          )}
          {(currentView === AppView.TEACHER_DASHBOARD || currentView === AppView.INCORRECT_NOTE) && (
             <button 
               onClick={handleLogout}
               className="text-sm text-gray-500 hover:text-red-600 font-medium transition-colors"
             >
               Close
             </button>
          )}
        </div>
      </header>

      <main className="max-w-4xl mx-auto px-4 py-8">
        {isLoading ? (
          <div className="flex flex-col items-center justify-center h-96 animate-pop">
             <div className="w-16 h-16 border-4 border-indigo-200 border-t-indigo-600 rounded-full animate-spin mb-6"></div>
             <p className="text-lg text-gray-600 font-medium">{loadingMessage}</p>
             <p className="text-sm text-gray-400 mt-2">Connecting to Google Sheet...</p>
          </div>
        ) : (
          <>
            {currentView === AppView.LANDING && (
              <Landing 
                onStart={handleStartQuiz} 
                onChangeView={setCurrentView}
              />
            )}

            {currentView === AppView.QUIZ && (
              <Quiz 
                questions={questions} 
                onComplete={handleQuizComplete} 
              />
            )}

            {currentView === AppView.RESULT && lastResult && (
              <Result 
                result={lastResult} 
                onHome={handleLogout} 
                submissionStatus={submissionStatus}
              />
            )}

            {currentView === AppView.INCORRECT_NOTE && (
              <IncorrectNote 
                initialStudentName={session?.name}
                incorrectRecords={incorrectRecords}
                onStartReview={(qs, name) => handleStartReview(qs, name)}
                onBack={() => setCurrentView(AppView.LANDING)}
              />
            )}

            {currentView === AppView.TEACHER_LOGIN && (
              <div className="max-w-md mx-auto bg-white p-8 rounded-2xl shadow-lg border border-gray-100 animate-pop">
                <h2 className="text-2xl font-bold mb-6 text-center">Teacher Login</h2>
                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Access Code</label>
                    <input 
                      type="password" 
                      value={accessCode}
                      onChange={(e) => setAccessCode(e.target.value)}
                      onKeyDown={(e) => e.key === 'Enter' && handleLogin()}
                      className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
                      placeholder="Enter code"
                    />
                    {loginError && <p className="text-red-500 text-sm mt-1">{loginError}</p>}
                    <p className="text-gray-400 text-xs mt-2 text-right">Default code: <code>teacher</code></p>
                  </div>
                  <button 
                    onClick={handleLogin}
                    className="w-full bg-gray-900 text-white py-2 rounded-lg hover:bg-black transition-colors"
                  >
                    Enter Dashboard
                  </button>
                  <button 
                    onClick={() => setCurrentView(AppView.LANDING)}
                    className="w-full text-gray-500 py-2 text-sm hover:text-gray-700"
                  >
                    Cancel
                  </button>
                </div>
              </div>
            )}

            {currentView === AppView.TEACHER_DASHBOARD && (
              <TeacherDashboard />
            )}
          </>
        )}
      </main>
    </div>
  );
}

export default App;

import React, { useState } from 'react';
import { QuizResult } from '../types';
import Button from '../components/Button';

interface ResultProps {
  result: QuizResult;
  onHome: () => void;
  submissionStatus?: 'idle' | 'submitting' | 'success' | 'error';
}

const Result: React.FC<ResultProps> = ({ result, onHome, submissionStatus = 'idle' }) => {
  const [copied, setCopied] = useState(false);
  const percentage = Math.round((result.score / result.totalQuestions) * 100);

  let gradeColor = 'text-red-500';
  let message = 'Keep practicing!';

  if (percentage >= 90) {
    gradeColor = 'text-green-500';
    message = 'Excellent work!';
  } else if (percentage >= 70) {
    gradeColor = 'text-blue-500';
    message = 'Good job!';
  } else if (percentage >= 50) {
    gradeColor = 'text-yellow-500';
    message = 'You can do better!';
  }

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}m ${s}s`;
  };

  const handleCopyResult = () => {
    const text = `[VocaMaster Result]\nStudent: ${result.studentName}\nDate/Tab: ${result.date}\nScore: ${result.score} / ${result.totalQuestions} (${percentage}%)\nTime: ${formatTime(result.timeTakenSeconds)}`;
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="flex flex-col items-center justify-center animate-pop py-8">
      <div className="bg-white rounded-3xl shadow-xl overflow-hidden max-w-lg w-full border border-gray-100">
        <div className="bg-gray-900 text-white p-8 text-center relative overflow-hidden">
          {/* Decorative circles */}
          <div className="absolute top-0 left-0 -translate-x-1/2 -translate-y-1/2 w-32 h-32 bg-white opacity-10 rounded-full"></div>
          <div className="absolute bottom-0 right-0 translate-x-1/2 translate-y-1/2 w-48 h-48 bg-indigo-500 opacity-20 rounded-full"></div>

          <h2 className="text-3xl font-bold relative z-10 mb-2">{result.studentName}</h2>
          <p className="text-gray-400 text-sm relative z-10">{result.date}</p>
        </div>

        <div className="p-8 text-center">
          <div className="mb-2 text-gray-500 text-sm font-semibold uppercase tracking-wider">Your Score</div>
          <div className={`text-6xl font-extrabold mb-2 ${gradeColor}`}>
            {result.score} <span className="text-2xl text-gray-400 font-normal">/ {result.totalQuestions}</span>
          </div>
          <p className="text-gray-600 font-medium text-lg mb-8">{message}</p>

          <div className="grid grid-cols-2 gap-4 mb-8">
            <div className="bg-gray-50 p-4 rounded-xl">
              <div className="text-gray-400 text-xs uppercase font-bold mb-1">Time Taken</div>
              <div className="text-xl font-bold text-gray-800">{formatTime(result.timeTakenSeconds)}</div>
            </div>
            <div className="bg-gray-50 p-4 rounded-xl">
              <div className="text-gray-400 text-xs uppercase font-bold mb-1">Accuracy</div>
              <div className="text-xl font-bold text-gray-800">{percentage}%</div>
            </div>
          </div>

          {submissionStatus !== 'idle' && (
             <div className="mb-6 p-3 rounded-lg text-sm font-medium">
               {submissionStatus === 'submitting' && (
                 <span className="text-gray-600 flex items-center justify-center gap-2">
                   <div className="w-3 h-3 border-2 border-gray-400 border-t-transparent rounded-full animate-spin"></div>
                   Saving result to Google Sheet...
                 </span>
               )}
               {submissionStatus === 'success' && (
                 <span className="text-green-600 flex items-center justify-center gap-2">
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
                    Result saved to Google Sheet!
                 </span>
               )}
               {submissionStatus === 'error' && (
                 <span className="text-red-500">
                    Failed to auto-save. Please copy the result below.
                 </span>
               )}
             </div>
          )}

          <div className="space-y-3">
            <Button 
              onClick={handleCopyResult} 
              fullWidth 
              size="lg"
              variant="secondary"
              className={copied ? "bg-green-50 text-green-700 border-green-200" : ""}
            >
              {copied ? (
                <span className="flex items-center justify-center gap-2">
                  <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
                  Copied!
                </span>
              ) : (
                "Copy Result (Submit to Teacher)"
              )}
            </Button>

            <Button onClick={onHome} fullWidth variant="ghost">
              Back to Home
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Result;

import React, { useEffect, useState } from 'react';
import { QuizResult } from '../types';
import Button from '../components/Button';

const STORAGE_KEY = 'vocamaster_results';
const SHEET_ID_KEY = 'vocamaster_sheet_id';
const SCRIPT_URL_KEY = 'vocamaster_script_url';

const TeacherDashboard: React.FC = () => {
  const [results, setResults] = useState<QuizResult[]>([]);
  const [sheetId, setSheetId] = useState('');
  const [scriptUrl, setScriptUrl] = useState('');
  const [isSaved, setIsSaved] = useState(false);
  const [isCopied, setIsCopied] = useState(false);

  useEffect(() => {
    // Load Results
    const storedResults = localStorage.getItem(STORAGE_KEY);
    if (storedResults) {
      try {
        const parsed = JSON.parse(storedResults) as QuizResult[];
        parsed.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
        setResults(parsed);
      } catch (e) {
        console.error("Failed to parse results");
      }
    }

    // Load Sheet ID and Script URL
    const storedSheetId = localStorage.getItem(SHEET_ID_KEY);
    if (storedSheetId) setSheetId(storedSheetId);

    const storedScriptUrl = localStorage.getItem(SCRIPT_URL_KEY);
    if (storedScriptUrl) setScriptUrl(storedScriptUrl);
  }, []);

  const handleSaveConfig = () => {
    // Extract ID if full URL is pasted for Sheet ID
    let cleanId = sheetId.trim();
    const urlMatch = cleanId.match(/\/d\/([a-zA-Z0-9-_]+)/);
    if (urlMatch) {
      cleanId = urlMatch[1];
    }

    localStorage.setItem(SHEET_ID_KEY, cleanId);
    setSheetId(cleanId);

    // Save Script URL
    if (scriptUrl.trim()) {
      localStorage.setItem(SCRIPT_URL_KEY, scriptUrl.trim());
    } else {
      localStorage.removeItem(SCRIPT_URL_KEY);
    }

    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
  };

  const handleCopyLink = () => {
    const origin = window.location.origin + window.location.pathname;
    // Include both sheet_id and script_url in the link if available
    let link = `${origin}?sheet_id=${sheetId}`;

    // We base64 encode the script URL to avoid URL parsing issues with parameters
    if (scriptUrl) {
      const encodedUrl = btoa(scriptUrl);
      link += `&script=${encodedUrl}`;
    }

    navigator.clipboard.writeText(link);
    setIsCopied(true);
    setTimeout(() => setIsCopied(false), 2000);
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
  };

  const formatDate = (isoString: string) => {
    return new Date(isoString).toLocaleString();
  };

  const clearData = () => {
    if (confirm("Are you sure you want to clear all student records on this device?")) {
      localStorage.removeItem(STORAGE_KEY);
      setResults([]);
    }
  };

  return (
    <div className="animate-pop space-y-8">
      {/* Settings Section */}
      <div className="bg-white rounded-xl shadow-md border border-indigo-100 p-6">
        <h3 className="text-xl font-bold text-indigo-900 mb-4 flex items-center gap-2">
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
            <path strokeLinecap="round" strokeLinejoin="round" d="M10.343 3.94c.09-.542.56-.94 1.11-.94h1.093c.55 0 1.02.398 1.11.94l.149.894c.07.424.384.764.78.93.398.164.855.142 1.205-.108l.737-.527a1.125 1.125 0 011.45.12l.773.774c.39.389.44 1.002.12 1.45l-.527.737c-.25.35-.272.806-.107 1.204.165.397.505.71.93.78l.893.15c.543.09.94.56.94 1.109v1.094c0 .55-.397 1.02-.94 1.11l-.893.149c-.425.07-.765.383-.93.78-.165.398-.143.854.107 1.204l.527.738c.32.447.269 1.06-.12 1.45l-.774.773a1.125 1.125 0 01-1.449.12l-.738-.527c-.35-.25-.806-.272-1.203-.107-.397.165-.71.505-.781.929l-.149.894c-.09.542-.56.94-1.11.94h-1.094c-.55 0-1.019-.398-1.11-.94l-.148-.894c-.071-.424-.384-.764-.781-.93-.398-.164-.854-.142-1.204.108l-.738.527c-.447.32-1.06.269-1.45-.12l-.773-.774a1.125 1.125 0 01-.12-1.45l.527-.737c.25-.35.273-.806.108-1.204-.165-.397-.505-.71-.93-.78l-.894-.15c-.542-.09-.94-.56-.94-1.109v-1.094c0-.55.398-1.02.94-1.11l.894-.149c.424-.07.765-.383.93-.78.165-.398.143-.854-.107-1.204l-.527-.738a1.125 1.125 0 01.12-1.45l.773-.773a1.125 1.125 0 011.45-.12l.737.527c.35.25.807.272 1.204.107.397-.165.71-.505.78-.929l.15-.894z" />
            <path strokeLinecap="round" strokeLinejoin="round" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
          </svg>
          DataSource Configuration
        </h3>

        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Google Sheet ID</label>
            <input 
              type="text" 
              value={sheetId}
              onChange={(e) => setSheetId(e.target.value)}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none font-mono text-sm"
              placeholder="Paste Sheet ID here..."
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Google Apps Script URL (For Auto-Saving Results)
              <span className="ml-2 text-xs font-normal text-gray-500 bg-gray-100 px-2 py-0.5 rounded">Optional</span>
            </label>
            <input 
              type="text" 
              value={scriptUrl}
              onChange={(e) => setScriptUrl(e.target.value)}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none font-mono text-sm"
              placeholder="https://script.google.com/macros/s/.../exec"
            />

            <div className="mt-3 bg-yellow-50 border border-yellow-200 rounded-md p-3">
              <div className="flex">
                <div className="flex-shrink-0">
                  <svg className="h-5 w-5 text-yellow-400" viewBox="0 0 20 20" fill="currentColor">
                    <path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
