                    <ol className="list-decimal list-inside space-y-1">
                      <li>Click the <strong>Advanced</strong> link on the warning screen.</li>
                      <li>Click <strong>Go to ... (unsafe)</strong> at the bottom.</li>
                      <li>Type "Continue" if prompted, then click <strong>Allow</strong>.</li>
                    </ol>
                  </div>
                </div>
              </div>
            </div>
          </div>

          <div className="pt-2">
            <Button onClick={handleSaveConfig} fullWidth>
              {isSaved ? 'Settings Saved!' : 'Save Settings'}
            </Button>
          </div>

          {sheetId && (
            <div className="bg-indigo-50 p-4 rounded-lg border border-indigo-100 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 mt-4">
               <div className="text-sm text-indigo-800">
                 <strong className="block mb-1">Distribution Link for Students</strong>
                 Sends students a link pre-configured with the Sheet ID {scriptUrl && "& Script URL"}.
               </div>
               <Button variant="secondary" size="sm" onClick={handleCopyLink} className="whitespace-nowrap">
                 {isCopied ? 'Link Copied!' : 'Copy Invite Link'}
               </Button>
            </div>
          )}

          <div className="bg-gray-50 p-4 rounded-lg text-sm text-gray-600 border border-gray-200 mt-4">
            <strong>How to enable auto-save:</strong>
            <ol className="list-decimal list-inside mt-2 space-y-1">
              <li>In your Google Sheet, go to <strong>Extensions {'>'} Apps Script</strong>.</li>
              <li>Paste the backend script code (found in documentation).</li>
              <li>Click <strong>Deploy {'>'} New deployment</strong>.</li>
              <li>Select <strong>Web app</strong>, set "Who has access" to <strong>"Anyone"</strong>.</li>
              <li>Copy the Web App URL and paste it above.</li>
            </ol>
          </div>
        </div>
      </div>

      {/* Results Section */}
      <div>
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-2xl font-bold text-gray-800">Student Results (Local Only)</h2>
          <button 
            onClick={clearData}
            className="text-red-600 hover:text-red-800 text-sm font-medium hover:underline"
          >
            Clear Data
          </button>
        </div>

        <div className="bg-amber-50 border-l-4 border-amber-500 p-4 mb-6">
          <div className="flex">
            <div className="flex-shrink-0">
              <svg className="h-5 w-5 text-amber-400" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
              </svg>
            </div>
            <div className="ml-3">
              <p className="text-sm text-amber-700">
                <strong>Note:</strong> This table only shows results from <em>this device</em>. 
                If you configured the <strong>Apps Script URL</strong> above, check your Google Sheet "Results" tab for all student submissions.
              </p>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-xl shadow-md border border-gray-200 overflow-hidden">
          {results.length === 0 ? (
            <div className="p-12 text-center text-gray-500">
              <p>No tests taken on this device yet.</p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-gray-50 border-b border-gray-200">
                    <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Tab Name</th>
                    <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Student Name</th>
                    <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Score</th>
                    <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Time Taken</th>
                    <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Timestamp</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {results.map((r, idx) => (
                    <tr key={idx} className="hover:bg-gray-50 transition-colors">
                      <td className="px-6 py-4 text-sm text-gray-900 font-medium">{r.date}</td>
                      <td className="px-6 py-4 text-sm text-gray-700">{r.studentName}</td>
                      <td className="px-6 py-4">
                        <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
                          (r.score / r.totalQuestions) > 0.8 ? 'bg-green-100 text-green-800' : 
                          (r.score / r.totalQuestions) > 0.5 ? 'bg-yellow-100 text-yellow-800' : 
                          'bg-red-100 text-red-800'
                        }`}>
                          {r.score} / {r.totalQuestions}
                        </span>
                      </td>
                      <td className="px-6 py-4 text-sm text-gray-500 font-mono">{formatTime(r.timeTakenSeconds)}</td>
                      <td className="px-6 py-4 text-sm text-gray-400">{formatDate(r.timestamp)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

