                  </button>
                  <span className="text-gray-300">|</span>
                  <button 
                    type="button" 
                    onClick={() => loadTabs(sheetId)}
                    className="text-indigo-600 hover:text-indigo-800 underline"
                  >
                    Retry List
                  </button>
                </div>
              )}
