    // Simplest possible URL construction to avoid environment-specific URL object issues
    const baseUrl = window.location.href.split('?')[0].split('#')[0];
    const params = new URLSearchParams();

    if (sheetId) {
      params.set('sheet_id', sheetId.trim());
    }

    if (scriptUrl) {
      // Send as plain text to avoid double encoding or btoa issues
      params.set('script', scriptUrl.trim());
    }

    const queryString = params.toString();
    return queryString ? `${baseUrl}?${queryString}` : baseUrl;
  };

  const handleCopyLink = () => {
    navigator.clipboard.writeText(getShareUrl());
    setIsCopied(true);
    setTimeout(() => setIsCopied(false), 2000);
  };

