                </svg>
                <div className="text-sm text-amber-900">
                  <p className="font-bold text-base mb-1">Setup Required</p>
                  <p>The vocabulary list source (Google Sheet) has not been connected yet.</p>
                </div>
              </div>
              <Button 
                type="button"
                variant="secondary"
