  const [baseUrl, setBaseUrl] = useState('');

  const [isSaved, setIsSaved] = useState(false);
  const [isCopied, setIsCopied] = useState(false);
  const [showQr, setShowQr] = useState(false);

  useEffect(() => {
    // Load Results
    const storedResults = localStorage.getItem(STORAGE_KEY);
    if (storedResults) {
      try {
        const parsed = JSON.parse(storedResults) as QuizResult[];
        parsed.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
        setResults(parsed);
      } catch (e) {
        console.error("Failed to parse results");
      }
    }

    // Load Sheet ID and Script URL
    const storedSheetId = localStorage.getItem(SHEET_ID_KEY);
    if (storedSheetId) setSheetId(storedSheetId);

    const storedScriptUrl = localStorage.getItem(SCRIPT_URL_KEY);
    if (storedScriptUrl) setScriptUrl(storedScriptUrl);

    // Initialize Base URL
    const currentHref = window.location.origin + window.location.pathname;
    setBaseUrl(currentHref);
  }, []);

  const handleSaveConfig = () => {
    // Extract ID if full URL is pasted for Sheet ID
    let cleanId = sheetId.trim();
    const urlMatch = cleanId.match(/\/d\/([a-zA-Z0-9-_]+)/);
    if (urlMatch) {
      cleanId = urlMatch[1];
    }

    localStorage.setItem(SHEET_ID_KEY, cleanId);
    setSheetId(cleanId);

    // Save Script URL
    if (scriptUrl.trim()) {
      localStorage.setItem(SCRIPT_URL_KEY, scriptUrl.trim());
    } else {
      localStorage.removeItem(SCRIPT_URL_KEY);
    }

    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
  };

  const getShareUrl = () => {
    const params = new URLSearchParams();
    if (sheetId) params.set('sheet_id', sheetId.trim());
    if (scriptUrl) params.set('script', scriptUrl.trim());

    const qs = params.toString();
    const cleanBase = baseUrl.trim();
    const connector = cleanBase.includes('?') ? '&' : '?';

    return qs ? `${cleanBase}${connector}${qs}` : cleanBase;
  };

  const handleCopyLink = () => {
    navigator.clipboard.writeText(getShareUrl());
    setIsCopied(true);
    setTimeout(() => setIsCopied(false), 2000);
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
  };

  const formatDate = (isoString: string) => {
    return new Date(isoString).toLocaleString();
  };

  const clearData = () => {
    if (confirm("이 브라우저에 저장된 모든 학생 응시 기록을 삭제하시겠습니까?")) {
      localStorage.removeItem(STORAGE_KEY);
      setResults([]);
    }
  };

  const shareUrl = getShareUrl();

  // Validation Logic (Warning only, not blocking)
  const isBlob = baseUrl.startsWith('blob:');
  const isLocal = baseUrl.includes('localhost') || baseUrl.includes('127.0.0.1') || baseUrl.startsWith('file:');
  const isEditorUrl = 
    baseUrl.includes('aistudio.google.com') || 
    baseUrl.includes('script.google.com') || 
    baseUrl.includes('colab.research.google.com');

  return (
    <div className="animate-pop space-y-8 pb-10">
      {/* Settings Section */}
      <div className="bg-white rounded-xl shadow-md border border-indigo-100 p-6">
        <h3 className="text-xl font-bold text-indigo-900 mb-4 flex items-center gap-2">
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
            <path strokeLinecap="round" strokeLinejoin="round" d="M10.343 3.94c.09-.542.56-.94 1.11-.94h1.093c.55 0 1.02.398 1.11.94l.149.894c.07.424.384.764.78.93.398.164.855.142 1.205-.108l.737-.527a1.125 1.125 0 011.45.12l.773.774c.39.389.44 1.002.12 1.45l-.527.737c-.25.35-.272.806-.107 1.204.165.397.505.71.93.78l.893.15c.543.09.94.56.94 1.109v1.094c0 .55-.397 1.02-.94 1.11l-.893.149c-.425.07-.765.383-.93.78-.165.398-.143.854.107 1.204l.527.738c.32.447.269 1.06-.12 1.45l-.774.773a1.125 1.125 0 01-.12-1.45l.527-.737c.25-.35.273-.806.108-1.204-.165-.397-.505-.71-.93.78l-.894-.15c-.542-.09-.94-.56-.94-1.109v-1.094c0-.55.398-1.02.94-1.11l.894-.149c.424-.07.765-.383.93-.78.165-.398.143-.854-.107-1.204l-.527-.738a1.125 1.125 0 01.12-1.45l.773-.773a1.125 1.125 0 011.45-.12l.737.527c.35.25.807.272 1.204.107.397-.165.71-.505.78-.929l.15-.894z" />
            <path strokeLinecap="round" strokeLinejoin="round" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
          </svg>
          환경 설정
        </h3>

        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">구글 시트 ID</label>
            <input 
              type="text" 
              value={sheetId}
              onChange={(e) => setSheetId(e.target.value)}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none font-mono text-sm"
              placeholder="시트 URL에서 ID를 복사해 붙여넣으세요..."
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Google Apps Script URL (결과 자동저장용)
            </label>
            <input 
              type="text" 
              value={scriptUrl}
              onChange={(e) => setScriptUrl(e.target.value)}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none font-mono text-sm"
              placeholder="https://script.google.com/macros/s/.../exec"
            />
          </div>

          <div className="pt-2">
            <Button onClick={handleSaveConfig} fullWidth>
              {isSaved ? '저장 완료!' : '설정 저장'}
            </Button>
          </div>

          {sheetId && (
            <div className="mt-8 border-t border-gray-100 pt-6">
               <h4 className="text-md font-bold text-gray-800 mb-4">학생 배포용 링크 생성</h4>

               <div className="mb-4 bg-gray-50 p-4 rounded-lg border border-gray-200">
                 <label className="block text-xs font-bold text-gray-700 mb-2">
                   현재 앱 주소 (자동 감지됨)
                 </label>
                 <input 
                    type="text" 
                    value={baseUrl}
                    onChange={(e) => setBaseUrl(e.target.value)}
                    className={`w-full px-3 py-2 text-sm border rounded-lg focus:outline-none border-gray-300 text-gray-600 focus:border-indigo-500`}
                    placeholder="https://your-app-url.vercel.app"
                 />

                 {(isBlob || isLocal || isEditorUrl) && (
                   <div className="mt-2 text-xs text-amber-600 font-medium bg-amber-50 p-2 border border-amber-200 rounded">
                     ⚠️ 알림: 현재 주소가 로컬이나 미리보기 환경입니다. 실제 배포 후에는 해당 주소를 입력하여 링크를 생성하세요.
                   </div>
                 )}
               </div>

               <div className="bg-indigo-50 p-4 rounded-lg border border-indigo-100 mb-4">
                 <label className="block text-xs font-bold text-indigo-800 mb-2 uppercase">초대용 전체 링크</label>
                 <div className="space-y-2">
                   <textarea
                      readOnly 
                      value={shareUrl} 
                      onClick={(e) => e.currentTarget.select()}
                      className="w-full h-16 px-3 py-2 text-xs bg-white border border-indigo-200 rounded text-gray-600 focus:outline-none resize-none font-mono break-all"
                   />
                   <div className="flex gap-2">
                      <Button variant="secondary" size="sm" onClick={handleCopyLink} className="flex-1 whitespace-nowrap">
                        {isCopied ? '복사 완료!' : '링크 복사'}
                      </Button>
                      <a 
                        href={shareUrl} 
                        target="_blank" 
                        rel="noopener noreferrer" 
                        className={`px-4 py-1.5 text-sm bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 flex items-center justify-center whitespace-nowrap`}
                      >
                        링크 테스트
                      </a>
                   </div>
                 </div>
               </div>

               <div className="text-center">
                 <Button onClick={() => setShowQr(!showQr)} variant="secondary" className="mb-4">
                   {showQr ? 'QR 코드 숨기기' : '수업용 QR 코드 생성'}
                 </Button>

                 {showQr && (
                   <div className="flex flex-col items-center justify-center p-6 bg-white border-2 border-dashed border-gray-300 rounded-xl animate-pop">
                     <div className="bg-white p-4 rounded-lg shadow-sm border border-gray-100">
                       <img 
                         src={`https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=${encodeURIComponent(shareUrl)}`} 
                         alt="Student Invite QR Code" 
                         className="w-48 h-48 md:w-64 md:h-64"
                         onLoad={() => console.log('QR Code Loaded')}
                         onError={(e) => {
                           console.error('QR Load Error');
                           (e.target as HTMLImageElement).src = 'https://via.placeholder.com/250?text=QR+Load+Failed';
                         }}
                       />
                     </div>
                     <p className="text-sm font-bold text-gray-600 mt-4">카메라로 스캔하여 시험 시작</p>
                     <p className="text-[10px] text-gray-400 mt-1">QR 제공: qrserver.com</p>
                   </div>
                 )}
               </div>
            </div>
          )}
        </div>
      </div>

      {/* Results Section */}
      <div>
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-2xl font-bold text-gray-800">최근 응시 결과 (이 브라우저)</h2>
          <button 
            onClick={clearData}
            className="text-red-600 hover:text-red-800 text-sm font-medium hover:underline"
          >
            기록 지우기
          </button>
        </div>

        <div className="bg-white rounded-xl shadow-md border border-gray-200 overflow-hidden">
          {results.length === 0 ? (
            <div className="p-12 text-center text-gray-500">
              <p>응시된 기록이 없습니다.</p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-gray-50 border-b border-gray-200">
                    <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">수업반</th>
                    <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">학생 이름</th>
                    <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">점수</th>
                    <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">소요 시간</th>
                    <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">응시 일시</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {results.map((r, idx) => (
                    <tr key={idx} className="hover:bg-gray-50 transition-colors">
                      <td className="px-6 py-4 text-sm text-gray-900 font-medium">{r.date}</td>
                      <td className="px-6 py-4 text-sm text-gray-700">{r.studentName}</td>
                      <td className="px-6 py-4">
                        <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
                          (r.score / r.totalQuestions) > 0.8 ? 'bg-green-100 text-green-800' : 
                          (r.score / r.totalQuestions) > 0.5 ? 'bg-yellow-100 text-yellow-800' : 
                          'bg-red-100 text-red-800'
                        }`}>
                          {r.score} / {r.totalQuestions}
                        </span>
                      </td>
                      <td className="px-6 py-4 text-sm text-gray-500 font-mono">{formatTime(r.timeTakenSeconds)}</td>
                      <td className="px-6 py-4 text-sm text-gray-400">{formatDate(r.timestamp)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default TeacherDashboard;

export interface Question {
  id: number;
  word: string;
  options: string[];
  correctAnswerIndex: number;
}

export interface QuizResult {
  studentName: string;
  className: string;
  date: string; // Test Date (YYYY-MM-DD)
  score: number;
  totalQuestions: number;
  timeTakenSeconds: number;
  timestamp: string; // ISO string
}

export interface IncorrectWord {
  question: Question;
  wrongCount: number;
  lastMissedDate: string;
}

export interface StudentIncorrectRecord {
  studentName: string;
  words: IncorrectWord[];
}

export enum AppView {
  LANDING = 'LANDING',
  QUIZ = 'QUIZ',
  RESULT = 'RESULT',
  TEACHER_LOGIN = 'TEACHER_LOGIN',
  TEACHER_DASHBOARD = 'TEACHER_DASHBOARD',
  INCORRECT_NOTE = 'INCORRECT_NOTE',
}

export interface UserSession {
  name: string;
  className: string;
  testDate: string;
}

export interface SheetWord {
  word: string;
  meaning: string;
}

import React, { useState, useEffect } from 'react';
import { AppView, UserSession, QuizResult, Question, IncorrectWord } from './types';
import Landing from './views/Landing';
import Quiz from './views/Quiz';
import Result from './views/Result';
import TeacherDashboard from './views/TeacherDashboard';
import IncorrectNote from './views/IncorrectNote';
import { generateQuizQuestions } from './services/geminiService';
import { fetchWordsFromSheet, submitResultToSheet } from './services/sheetService';

const RESULT_STORAGE_KEY = 'vocamaster_results';
const INCORRECT_STORAGE_KEY = 'vocamaster_incorrect_notes';
const SHEET_ID_KEY = 'vocamaster_sheet_id';
const SCRIPT_URL_KEY = 'vocamaster_script_url';

function App() {
  const [currentView, setCurrentView] = useState<AppView>(AppView.LANDING);
  const [session, setSession] = useState<UserSession | null>(null);
  const [questions, setQuestions] = useState<Question[]>([]);
  const [lastResult, setLastResult] = useState<QuizResult | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [loadingMessage, setLoadingMessage] = useState('');
  const [submissionStatus, setSubmissionStatus] = useState<'idle' | 'submitting' | 'success' | 'error'>('idle');

  const [isReviewMode, setIsReviewMode] = useState(false);
  const [incorrectRecords, setIncorrectRecords] = useState<Record<string, IncorrectWord[]>>({});

  // Login State
  const [accessCode, setAccessCode] = useState('');
  const [loginError, setLoginError] = useState('');

  useEffect(() => {
    const stored = localStorage.getItem(INCORRECT_STORAGE_KEY);
    if (stored) {
      try {
        setIncorrectRecords(JSON.parse(stored));
      } catch (e) {
        console.error("Failed to load incorrect records");
      }
    }
  }, []);

  const saveResult = (result: QuizResult) => {
    const existing = localStorage.getItem(RESULT_STORAGE_KEY);
    const results: QuizResult[] = existing ? JSON.parse(existing) : [];
    results.push(result);
    localStorage.setItem(RESULT_STORAGE_KEY, JSON.stringify(results));
    setLastResult(result);

    const scriptUrl = localStorage.getItem(SCRIPT_URL_KEY);
    if (scriptUrl) {
      setSubmissionStatus('submitting');
      submitResultToSheet(scriptUrl, result).then(success => {
        setSubmissionStatus(success ? 'success' : 'error');
      });
    } else {
      setSubmissionStatus('idle');
    }
  };

  const updateIncorrectWords = (studentName: string, quizQuestions: Question[], wrongQuestions: Question[]) => {
    const records = { ...incorrectRecords };
    let studentKey = Object.keys(records).find(k => k.toLowerCase() === studentName.toLowerCase().trim());

    if (!studentKey) {
      studentKey = studentName.trim();
      records[studentKey] = [];
    }

    const studentWords = records[studentKey];
    const now = new Date().toISOString();

    if (isReviewMode) {
      const wrongIds = new Set(wrongQuestions.map(q => q.id));
      const correctIds = quizQuestions.filter(q => !wrongIds.has(q.id)).map(q => q.id);

      records[studentKey] = studentWords.map(w => {
         if (correctIds.includes(w.question.id)) {
           return { ...w, wrongCount: Math.max(0, w.wrongCount - 1) };
         }
         return w;
      }).filter(w => w.wrongCount > 0);

      records[studentKey] = records[studentKey].map(w => {
        if (wrongIds.has(w.question.id)) {
           return { ...w, wrongCount: w.wrongCount + 1, lastMissedDate: now };
        }
        return w;
      });
    } else {
      wrongQuestions.forEach(q => {
        const existingIndex = studentWords.findIndex(w => w.question.word === q.word);
        if (existingIndex >= 0) {
          studentWords[existingIndex].wrongCount += 1;
          studentWords[existingIndex].lastMissedDate = now;
          studentWords[existingIndex].question = q; 
        } else {
          studentWords.push({
            question: q,
            wrongCount: 1,
            lastMissedDate: now
          });
        }
      });
    }

    setIncorrectRecords(records);
    localStorage.setItem(INCORRECT_STORAGE_KEY, JSON.stringify(records));
  };

  const handleStartQuiz = async (name: string, className: string, testDate: string) => {
    setSession({ name, className, testDate });
    setIsLoading(true);
    setLoadingMessage(`구글 시트 '${className}' 반 데이터에 연결 중...`);
    setIsReviewMode(false);
    setSubmissionStatus('idle');

    try {
      const sheetId = localStorage.getItem(SHEET_ID_KEY);
      if (!sheetId) {
        throw new Error("선생님 설정이 완료되지 않았습니다. 시트 ID를 입력해주세요.");
      }

      const sheetWords = await fetchWordsFromSheet(sheetId, className);

      const count = Math.min(sheetWords.length, 50);
      setLoadingMessage(`${className} 반의 단어 ${count}개를 무작위로 추출하여 시험지를 생성 중입니다...`);

      const generatedQuestions = await generateQuizQuestions(testDate, sheetWords);

      setQuestions(generatedQuestions);
      setCurrentView(AppView.QUIZ);

    } catch (error: any) {
      alert(`오류 발생: ${error.message}\n\n시트 ID와 수업반 명칭(탭 이름)을 확인하고, 시트가 '공개' 상태인지 확인해주세요.`);
      console.error(error);
      setSession(null);
    } finally {
      setIsLoading(false);
    }
  };

  const handleStartReview = (reviewQuestions: Question[], studentName?: string) => {
    if (studentName) {
      setSession({ name: studentName, className: '오답 복습', testDate: new Date().toISOString().split('T')[0] });
    }
    setQuestions(reviewQuestions);
    setIsReviewMode(true);
    setCurrentView(AppView.QUIZ);
  };

  const handleQuizComplete = (score: number, total: number, timeSeconds: number, wrongQuestions: Question[]) => {
    if (!session && !isReviewMode) return;

    const nameToUse = session?.name || "익명 학생";
    updateIncorrectWords(nameToUse, questions, wrongQuestions);

    const result: QuizResult = {
      studentName: nameToUse,
      className: session?.className || "복습 모드",
      date: session?.testDate || new Date().toISOString().split('T')[0],
      score,
      totalQuestions: total,
      timeTakenSeconds: timeSeconds,
      timestamp: new Date().toISOString(),
    };

    if (!isReviewMode) {
      saveResult(result);
    } else {
      setLastResult(result);
    }

    setCurrentView(AppView.RESULT);
  };

  const handleLogin = () => {
    if (accessCode === 'teacher') {
      setLoginError('');
      setAccessCode('');
      setCurrentView(AppView.TEACHER_DASHBOARD);
    } else {
      setLoginError('비밀번호가 틀렸습니다. (기본: teacher)');
    }
  };

  const handleLogout = () => {
    setSession(null);
    setQuestions([]);
    setLastResult(null);
    setIsReviewMode(false);
    setCurrentView(AppView.LANDING);
    setAccessCode('');
    setLoginError('');
  };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 font-sans">
      <header className="bg-white shadow-sm border-b border-gray-200 sticky top-0 z-10">
        <div className="max-w-4xl mx-auto px-4 py-4 flex justify-between items-center">
          <div 
            className="flex items-center gap-2 cursor-pointer" 
            onClick={() => setCurrentView(AppView.LANDING)}
          >
            <div className="bg-indigo-600 text-white p-2 rounded-lg">
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                <path strokeLinecap="round" strokeLinejoin="round" d="M12 6.042A8.967 8.967 0 006 3.75c-1.052 0-2.062.18-3 .512v14.25A8.987 8.987 0 016 18c2.305 0 4.408.867 6 2.292m0-14.25a8.966 8.966 0 016-2.292c1.052 0 2.062.18 3 .512v14.25A8.987 8.987 0 0018 18a8.967 8.967 0 00-6 2.292m0-14.25v14.25" />
              </svg>
            </div>
            <h1 className="text-xl font-bold text-gray-800 tracking-tight">PIF영어학원</h1>
          </div>

          {currentView === AppView.LANDING && (
             <div className="flex gap-4">
                <button 
                  onClick={() => setCurrentView(AppView.TEACHER_LOGIN)}
                  className="px-4 py-2 rounded-md bg-gray-100 hover:bg-gray-200 text-gray-700 font-medium text-sm transition-colors"
                >
                  선생님
                </button>
             </div>
          )}
          {(currentView === AppView.TEACHER_DASHBOARD || currentView === AppView.INCORRECT_NOTE || currentView === AppView.TEACHER_LOGIN) && (
             <button 
               onClick={handleLogout}
               className="text-sm text-gray-500 hover:text-red-600 font-medium transition-colors"
             >
               닫기
             </button>
          )}
        </div>
      </header>

      <main className="max-w-4xl mx-auto px-4 py-8">
        {isLoading ? (
          <div className="flex flex-col items-center justify-center h-96 animate-pop text-center">
             <div className="w-16 h-16 border-4 border-indigo-200 border-t-indigo-600 rounded-full animate-spin mb-6"></div>
             <p className="text-lg text-gray-600 font-semibold px-4">{loadingMessage}</p>
             <p className="text-sm text-gray-400 mt-2">AI가 시험지를 준비하고 있습니다...</p>
          </div>
        ) : (
          <>
            {currentView === AppView.LANDING && (
              <Landing 
                onStart={handleStartQuiz} 
                onChangeView={setCurrentView}
              />
            )}

            {currentView === AppView.QUIZ && (
              <Quiz 
                questions={questions} 
                onComplete={handleQuizComplete} 
              />
            )}

            {currentView === AppView.RESULT && lastResult && (
              <Result 
                result={lastResult} 
                onHome={handleLogout} 
                submissionStatus={submissionStatus}
              />
            )}

            {currentView === AppView.INCORRECT_NOTE && (
              <IncorrectNote 
                initialStudentName={session?.name}
                incorrectRecords={incorrectRecords}
                onStartReview={(qs, name) => handleStartReview(qs, name)}
                onBack={() => setCurrentView(AppView.LANDING)}
              />
            )}

            {currentView === AppView.TEACHER_LOGIN && (
              <div className="max-w-md mx-auto bg-white p-8 rounded-2xl shadow-lg border border-gray-100 animate-pop">
                <h2 className="text-2xl font-bold mb-6 text-center">선생님 로그인</h2>
                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">액세스 코드</label>
                    <input 
                      type="password" 
                      value={accessCode}
                      onChange={(e) => setAccessCode(e.target.value)}
                      onKeyDown={(e) => e.key === 'Enter' && handleLogin()}
                      className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
                      placeholder="비밀번호 입력"
                    />
                    {loginError && <p className="text-red-500 text-sm mt-1">{loginError}</p>}
                  </div>
                  <button 
                    onClick={handleLogin}
                    className="w-full bg-gray-900 text-white py-2 rounded-lg hover:bg-black transition-colors"
                  >
                    대시보드 입장
                  </button>
                  <button 
                    onClick={() => setCurrentView(AppView.LANDING)}
                    className="w-full text-gray-500 py-2 text-sm hover:text-gray-700"
                  >
                    취소
                  </button>
                </div>
              </div>
            )}

            {currentView === AppView.TEACHER_DASHBOARD && (
              <TeacherDashboard />
            )}
          </>
        )}
      </main>
    </div>
  );
}

export default App;

import React, { useState, useEffect } from 'react';
import Button from '../components/Button';
import { AppView } from '../types';
import { fetchSheetTabs } from '../services/sheetService';

interface LandingProps {
  onStart: (name: string, className: string, date: string) => void;
  onChangeView: (view: AppView) => void;
}

const Landing: React.FC<LandingProps> = ({ onStart, onChangeView }) => {
  const [name, setName] = useState('');
  const [className, setClassName] = useState('');
  const [testDate, setTestDate] = useState(new Date().toISOString().split('T')[0]);
  const [hasSheetId, setHasSheetId] = useState(false);

  // Default preset tabs as requested by the user
  const PRESET_TABS = ['서울고', '상문고', '서초고', '예비고1', '예비고2'];
  const [availableTabs, setAvailableTabs] = useState<string[]>(PRESET_TABS);
  const [isLoadingTabs, setIsLoadingTabs] = useState(false);
  const [isManualInput, setIsManualInput] = useState(false);

  useEffect(() => {
    const SHEET_KEY = 'vocamaster_sheet_id';
    const SCRIPT_KEY = 'vocamaster_script_url';

    const params = new URLSearchParams(window.location.search);
    const urlSheetId = params.get('sheet_id');
    const urlScript = params.get('script');

    if (urlSheetId) {
      localStorage.setItem(SHEET_KEY, urlSheetId);
      setHasSheetId(true);
      loadTabs(urlSheetId);
    } else {
      const storedSheetId = localStorage.getItem(SHEET_KEY);
      if (storedSheetId) {
        setHasSheetId(true);
        loadTabs(storedSheetId);
      }
    }

    if (urlScript) {
      const cleanScript = urlScript.trim();
      if (cleanScript.toLowerCase().startsWith('http')) {
        localStorage.setItem(SCRIPT_KEY, cleanScript);
      } else {
        try {
          const decoded = atob(cleanScript);
          localStorage.setItem(SCRIPT_KEY, decoded);
        } catch (e) {
          localStorage.setItem(SCRIPT_KEY, cleanScript);
        }
      }
    }

    if (urlSheetId || urlScript) {
       window.history.replaceState({}, document.title, window.location.pathname);
    }
  }, []);

  const loadTabs = async (id: string) => {
    setIsLoadingTabs(true);
    try {
      const tabs = await fetchSheetTabs(id);
      if (tabs && tabs.length > 0) {
        setAvailableTabs(tabs);
        setIsManualInput(false);
      } else {
        setAvailableTabs(PRESET_TABS);
      }
    } catch (e) {
      console.error("Failed to load tabs, using presets", e);
      setAvailableTabs(PRESET_TABS);
    } finally {
      setIsLoadingTabs(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (name.trim() && className.trim() && testDate) {
      onStart(name.trim(), className.trim(), testDate);
    }
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-[60vh] animate-pop pb-10">
      <div className="w-full max-w-xl bg-white rounded-3xl shadow-2xl overflow-hidden border border-indigo-50">
        <div className="bg-indigo-600 p-8 text-center relative overflow-hidden">
          <div className="absolute top-0 right-0 -mr-10 -mt-10 w-40 h-40 bg-white opacity-10 rounded-full blur-2xl"></div>
          <h2 className="text-3xl font-extrabold text-white mb-2 relative z-10">PIF영어학원 단어시험</h2>
          <p className="text-indigo-100 font-medium relative z-10 opacity-90">단어 실력이 곧 독해력입니다!</p>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-8">
          {!hasSheetId && (
            <div className="bg-amber-50 border border-amber-200 rounded-xl p-5 text-sm text-amber-900">
              <p className="font-bold mb-1">⚠️ 선생님 설정 필요</p>
              <p className="mb-3">관리자 설정을 완료한 후 시험을 시작할 수 있습니다.</p>
              <Button type="button" variant="secondary" fullWidth onClick={() => onChangeView(AppView.TEACHER_LOGIN)}>설정하러 가기</Button>
            </div>
          )}

          {/* 1. Date Selection */}
          <div className="animate-pop" style={{ animationDelay: '0.1s' }}>
            <label className="block text-xs font-black text-indigo-500 uppercase tracking-widest mb-1">Step 01</label>
            <h3 className="text-lg font-bold text-gray-800 mb-3">시험 날짜</h3>
            <input
              type="date"
              required
              value={testDate}
              onChange={(e) => setTestDate(e.target.value)}
              className="w-full px-4 py-3 rounded-xl border-2 border-gray-100 bg-gray-50 focus:bg-white focus:ring-4 focus:ring-indigo-100 focus:border-indigo-500 outline-none transition-all text-gray-700 font-semibold"
            />
          </div>

          {/* 2. Class Selection */}
          <div className="animate-pop" style={{ animationDelay: '0.2s' }}>
            <div className="flex justify-between items-end mb-3">
              <div>
                <label className="block text-xs font-black text-indigo-500 uppercase tracking-widest mb-1">Step 02</label>
                <h3 className="text-lg font-bold text-gray-800">수업반 선택</h3>
              </div>
              {isLoadingTabs && <div className="text-[10px] text-indigo-400 font-bold animate-pulse">탭 목록 로딩 중...</div>}
            </div>

            {isManualInput ? (
              <div className="relative">
                <input
                  type="text"
                  required
                  placeholder="반 이름을 직접 입력하세요"
                  value={className}
                  onChange={(e) => setClassName(e.target.value)}
                  className="w-full px-4 py-3 rounded-xl border-2 border-gray-100 bg-gray-50 focus:bg-white focus:ring-4 focus:ring-indigo-100 focus:border-indigo-500 outline-none transition-all font-semibold"
                />
                <button type="button" onClick={() => setIsManualInput(false)} className="absolute right-4 top-1/2 -translate-y-1/2 text-xs text-indigo-600 font-bold underline">목록보기</button>
              </div>
            ) : (
              <div className="space-y-3">
                <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
                  {availableTabs.map((tab) => (
                    <button
                      key={tab}
                      type="button"
                      onClick={() => setClassName(tab)}
                      className={`px-3 py-4 rounded-xl border-2 transition-all duration-200 text-sm font-bold h-14 flex items-center justify-center text-center
                        ${className === tab 
                          ? 'border-indigo-600 bg-indigo-600 text-white shadow-lg scale-105' 
                          : 'border-gray-50 bg-gray-50 text-gray-600 hover:border-indigo-200 hover:bg-white hover:text-indigo-600'}`}
                    >
                      {tab}
                    </button>
                  ))}
                </div>
                <div className="flex justify-center">
                   <button type="button" onClick={() => { setIsManualInput(true); setClassName(''); }} className="text-[11px] text-gray-400 hover:text-indigo-600 underline font-semibold">반 목록에 없나요?</button>
                </div>
              </div>
            )}
          </div>

          {/* 3. Name Entry */}
          <div className="animate-pop" style={{ animationDelay: '0.3s' }}>
            <label className="block text-xs font-black text-indigo-500 uppercase tracking-widest mb-1">Step 03</label>
            <h3 className="text-lg font-bold text-gray-800 mb-3">학생 이름</h3>
            <input
              type="text"
              required
              placeholder="예: 차은우"
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="w-full px-5 py-4 rounded-xl border-2 border-gray-100 bg-gray-50 focus:bg-white focus:ring-4 focus:ring-indigo-100 focus:border-indigo-500 outline-none transition-all text-xl font-bold text-gray-800 placeholder:text-gray-300"
            />
          </div>

          <div className="animate-pop pt-4" style={{ animationDelay: '0.4s' }}>
            <Button type="submit" fullWidth disabled={!hasSheetId || !className || !name || !testDate} className="text-xl py-5 shadow-2xl shadow-indigo-200 rounded-2xl">
              시험 시작하기
            </Button>
          </div>
        </form>
      </div>

      <div className="mt-8 w-full max-w-xl animate-pop" style={{ animationDelay: '0.5s' }}>
        <button onClick={() => onChangeView(AppView.INCORRECT_NOTE)} className="w-full flex items-center justify-between px-6 py-4 bg-white border border-red-50 text-red-600 rounded-2xl shadow-md hover:bg-red-50 transition-all font-bold">
          <span className="flex items-center gap-3">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3.75m9-.75a9 9 0 11-18 0 9 9 0 0118 0zm-9 3.75h.008v.008H12v-.008z" /></svg>
            나의 오답 노트
          </span>
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={3} stroke="currentColor" className="w-4 h-4"><path strokeLinecap="round" strokeLinejoin="round" d="M8.25 4.5l7.5 7.5-7.5 7.5" /></svg>
        </button>
      </div>
    </div>
  );
};

export default Landing;

import React, { useEffect, useState } from 'react';
import { QuizResult } from '../types';
import Button from '../components/Button';

const STORAGE_KEY = 'vocamaster_results';
const SHEET_ID_KEY = 'vocamaster_sheet_id';
const SCRIPT_URL_KEY = 'vocamaster_script_url';

const TeacherDashboard: React.FC = () => {
  const [results, setResults] = useState<QuizResult[]>([]);
  const [sheetId, setSheetId] = useState('');
  const [scriptUrl, setScriptUrl] = useState('');
  const [baseUrl, setBaseUrl] = useState('');

  const [isSaved, setIsSaved] = useState(false);
  const [isCopied, setIsCopied] = useState(false);
  const [showQr, setShowQr] = useState(false);
  const [qrLoading, setQrLoading] = useState(true);

  useEffect(() => {
    // Load Results
    const storedResults = localStorage.getItem(STORAGE_KEY);
    if (storedResults) {
      try {
        const parsed = JSON.parse(storedResults) as QuizResult[];
        parsed.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
        setResults(parsed);
      } catch (e) {
        console.error("Failed to parse results");
      }
    }

    // Load Sheet ID and Script URL
    const storedSheetId = localStorage.getItem(SHEET_ID_KEY);
    if (storedSheetId) setSheetId(storedSheetId);

    const storedScriptUrl = localStorage.getItem(SCRIPT_URL_KEY);
    if (storedScriptUrl) setScriptUrl(storedScriptUrl);

    // Initialize Base URL
    const currentHref = window.location.origin + window.location.pathname;
    setBaseUrl(currentHref);
  }, []);

  const handleSaveConfig = () => {
    let cleanId = sheetId.trim();
    const urlMatch = cleanId.match(/\/d\/([a-zA-Z0-9-_]+)/);
    if (urlMatch) {
      cleanId = urlMatch[1];
    }

    localStorage.setItem(SHEET_ID_KEY, cleanId);
    setSheetId(cleanId);

    if (scriptUrl.trim()) {
      localStorage.setItem(SCRIPT_URL_KEY, scriptUrl.trim());
    } else {
      localStorage.removeItem(SCRIPT_URL_KEY);
    }

    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
  };

  const getShareUrl = () => {
    const params = new URLSearchParams();
    if (sheetId) params.set('sheet_id', sheetId.trim());
    if (scriptUrl) params.set('script', scriptUrl.trim());

    const qs = params.toString();
    const cleanBase = baseUrl.trim();
    const connector = cleanBase.includes('?') ? '&' : '?';

    return qs ? `${cleanBase}${connector}${qs}` : cleanBase;
  };

  const handleCopyLink = () => {
    navigator.clipboard.writeText(getShareUrl());
    setIsCopied(true);
    setTimeout(() => setIsCopied(false), 2000);
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
  };

  const formatDate = (isoString: string) => {
    return new Date(isoString).toLocaleString();
  };

  const clearData = () => {
    if (confirm("이 브라우저에 저장된 모든 학생 응시 기록을 삭제하시겠습니까?")) {
      localStorage.removeItem(STORAGE_KEY);
      setResults([]);
    }
  };

  const shareUrl = getShareUrl();
  const qrUrl = `https://chart.googleapis.com/chart?cht=qr&chs=300x300&chl=${encodeURIComponent(shareUrl)}`;

  return (
    <div className="animate-pop space-y-8 pb-10">
      {/* Settings Section */}
      <div className="bg-white rounded-2xl shadow-lg border border-indigo-100 p-8">
        <h3 className="text-xl font-bold text-indigo-900 mb-6 flex items-center gap-2">
          ⚙️ 환경 설정
        </h3>

        <div className="space-y-6">
          <div>
            <label className="block text-sm font-bold text-gray-700 mb-1">구글 시트 ID</label>
            <input 
              type="text" 
              value={sheetId}
              onChange={(e) => setSheetId(e.target.value)}
              className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none font-mono text-sm"
              placeholder="시트 URL에서 ID를 복사해 붙여넣으세요"
            />
          </div>

          <div>
            <label className="block text-sm font-bold text-gray-700 mb-1">Apps Script URL (자동 저장용)</label>
            <input 
              type="text" 
              value={scriptUrl}
              onChange={(e) => setScriptUrl(e.target.value)}
              className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none font-mono text-sm"
              placeholder="https://script.google.com/..."
            />
          </div>

          <Button onClick={handleSaveConfig} fullWidth className="py-3">
            {isSaved ? '저장 완료!' : '설정 저장'}
          </Button>

          {sheetId && (
            <div className="mt-8 border-t border-gray-100 pt-8">
               <h4 className="text-md font-bold text-gray-800 mb-4">학생 배포</h4>

               <div className="bg-indigo-50 p-5 rounded-xl border border-indigo-100 mb-4">
                 <label className="block text-xs font-black text-indigo-800 mb-2 uppercase tracking-widest">초대 링크</label>
                 <div className="flex gap-2">
                    <input
                       readOnly 
                       value={shareUrl} 
                       className="flex-1 px-3 py-2 text-xs bg-white border border-indigo-200 rounded-lg text-gray-600 focus:outline-none font-mono"
                    />
                    <Button variant="secondary" size="sm" onClick={handleCopyLink} className="whitespace-nowrap px-4">
                      {isCopied ? '복사됨' : '복사'}
                    </Button>
                 </div>
               </div>

               <div className="text-center">
                 <Button onClick={() => { setShowQr(!showQr); setQrLoading(true); }} variant="secondary" className="mb-4">
                   {showQr ? 'QR 가리기' : '수업용 QR 코드 생성'}
                 </Button>

                 {showQr && (
                   <div className="flex flex-col items-center justify-center p-8 bg-gray-50 border-2 border-dashed border-gray-200 rounded-2xl animate-pop relative min-h-[300px]">
                     {qrLoading && (
                       <div className="absolute inset-0 flex items-center justify-center bg-gray-50/80 z-10 rounded-2xl">
                         <div className="w-8 h-8 border-3 border-indigo-200 border-t-indigo-600 rounded-full animate-spin"></div>
                       </div>
                     )}
                     <div className="bg-white p-6 rounded-2xl shadow-xl border border-gray-100 mb-4">
                       <img 
                         src={qrUrl} 
                         alt="QR" 
                         className="w-48 h-48 md:w-64 md:h-64"
                         onLoad={() => setQrLoading(false)}
                         onError={() => {
                           setQrLoading(false);
                           alert("QR 코드를 생성할 수 없습니다. 네트워크 연결을 확인하세요.");
                         }}
                       />
                     </div>
                     <p className="text-sm font-bold text-gray-600">카메라로 스캔하여 시험 시작</p>
                   </div>
                 )}
               </div>
            </div>
          )}
        </div>
      </div>

      {/* Results Table */}
      <div className="bg-white rounded-2xl shadow-lg border border-gray-200 overflow-hidden">
        <div className="p-6 border-b border-gray-100 flex justify-between items-center">
          <h2 className="text-xl font-bold text-gray-800">응시 기록</h2>
          <button onClick={clearData} className="text-red-500 hover:text-red-700 text-xs font-bold underline">기록 전체 삭제</button>
        </div>
        <div className="overflow-x-auto">
          {results.length === 0 ? (
            <div className="p-12 text-center text-gray-400 font-medium">기록이 없습니다.</div>
          ) : (
            <table className="w-full text-left">
              <thead>
                <tr className="bg-gray-50 border-b border-gray-100">
                  <th className="px-6 py-4 text-xs font-black text-gray-400 uppercase">날짜/반</th>
                  <th className="px-6 py-4 text-xs font-black text-gray-400 uppercase">이름</th>
                  <th className="px-6 py-4 text-xs font-black text-gray-400 uppercase">점수</th>
                  <th className="px-6 py-4 text-xs font-black text-gray-400 uppercase">시간</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {results.map((r, idx) => (
                  <tr key={idx} className="hover:bg-indigo-50/30 transition-colors">
                    <td className="px-6 py-4">
                      <div className="text-sm font-bold text-gray-800">{r.className}</div>
                      <div className="text-[10px] text-gray-400">{r.date}</div>
                    </td>
                    <td className="px-6 py-4 text-sm font-medium text-gray-700">{r.studentName}</td>
                    <td className="px-6 py-4">
                      <span className="font-mono font-bold text-indigo-600">{r.score}</span>
                      <span className="text-gray-300 text-xs mx-1">/</span>
                      <span className="text-gray-400 text-xs">{r.totalQuestions}</span>
                    </td>
                    <td className="px-6 py-4 text-xs font-mono text-gray-400">{formatTime(r.timeTakenSeconds)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </div>
  );
};

export default TeacherDashboard;

import React, { useState } from 'react';
import { QuizResult } from '../types';
import Button from '../components/Button';

interface ResultProps {
  result: QuizResult;
  onHome: () => void;
  submissionStatus?: 'idle' | 'submitting' | 'success' | 'error';
}

const Result: React.FC<ResultProps> = ({ result, onHome, submissionStatus = 'idle' }) => {
  const [copied, setCopied] = useState(false);
  const percentage = Math.round((result.score / result.totalQuestions) * 100);

  let gradeColor = 'text-red-500';
  let message = '조금 더 노력해봅시다!';

  if (percentage >= 90) {
    gradeColor = 'text-green-500';
    message = '훌륭합니다! 완벽해요!';
  } else if (percentage >= 70) {
    gradeColor = 'text-blue-500';
    message = '잘했습니다! 좋은 결과예요.';
  } else if (percentage >= 50) {
    gradeColor = 'text-yellow-500';
    message = '아쉬워요. 조금만 더 공부할까요?';
  }

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}분 ${s}초`;
  };

  const handleCopyResult = () => {
    const text = `[PIF 단어결과]\n이름: ${result.studentName}\n반/날짜: ${result.className} (${result.date})\n점수: ${result.score} / ${result.totalQuestions} (${percentage}%)\n시간: ${formatTime(result.timeTakenSeconds)}`;
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="flex flex-col items-center justify-center animate-pop py-8">
      <div className="bg-white rounded-3xl shadow-xl overflow-hidden max-w-lg w-full border border-gray-100">
        <div className="bg-gray-900 text-white p-8 text-center relative overflow-hidden">
          <div className="absolute top-0 left-0 -translate-x-1/2 -translate-y-1/2 w-32 h-32 bg-white opacity-5 rounded-full"></div>
          <h2 className="text-3xl font-bold relative z-10 mb-2">{result.studentName}</h2>
          <p className="text-gray-400 text-sm relative z-10 font-medium">{result.className} <span className="mx-2">|</span> {result.date}</p>
        </div>

        <div className="p-8 text-center">
          <div className="mb-2 text-gray-400 text-xs font-black uppercase tracking-widest">FINAL SCORE</div>
          <div className={`text-7xl font-black mb-4 ${gradeColor}`}>
            {result.score} <span className="text-2xl text-gray-300 font-normal">/ {result.totalQuestions}</span>
          </div>
          <p className="text-gray-600 font-bold text-lg mb-8">{message}</p>

          <div className="grid grid-cols-2 gap-3 mb-8">
            <div className="bg-gray-50 p-5 rounded-2xl border border-gray-100">
              <div className="text-gray-400 text-[10px] font-black uppercase mb-1">소요 시간</div>
              <div className="text-xl font-black text-gray-800">{formatTime(result.timeTakenSeconds)}</div>
