  const qrUrl = useMemo(() => {
    if (!shareUrl) return "";
    return `https://quickchart.io/qr?text=${encodeURIComponent(shareUrl)}&size=400&margin=2&ecLevel=H`;
  }, [shareUrl]);

  // Detect when QR image needs to show loading
  useEffect(() => {
    if (showQr && qrUrl) {
      setQrLoading(true);
      setQrError(false);
    }
  }, [qrUrl, showQr]);

