    if (urlMatch) cleanId = urlMatch[1];

    localStorage.setItem(SHEET_ID_KEY, cleanId);
    setSheetId(cleanId);
    if (scriptUrl.trim()) localStorage.setItem(SCRIPT_URL_KEY, scriptUrl.trim());
    else localStorage.removeItem(SCRIPT_URL_KEY);
