import { GoogleGenAI, Type } from "@google/genai";
import { Question, SheetWord } from "../types";

// Helper to shuffle array (Fisher-Yates)
const shuffleArray = <T,>(array: T[]): T[] => {
  const newArray = [...array];
  for (let i = newArray.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [newArray[i], newArray[j]] = [newArray[j], newArray[i]];
  }
  return newArray;
};

/**
 * Generates a quiz locally using sheet words as distractors.
 * This is used as a fallback when Gemini API hits quota limits.
 */
const generateLocalQuiz = (sheetWords: SheetWord[]): Question[] => {
  const shuffledSource = shuffleArray(sheetWords);
  const limitedWords = shuffledSource.slice(0, 50);

  // All meanings in the list to be used as distractor source
  const allMeanings = sheetWords.map(sw => sw.meaning);

  return limitedWords.map((sw, idx) => {
    const correctMeaning = sw.meaning;

    // Pick 3 random meanings from the rest of the list
    const otherMeanings = allMeanings.filter(m => m !== correctMeaning);
    const distractors = shuffleArray(otherMeanings).slice(0, 3);

    // Combine and shuffle options
    const options = shuffleArray([correctMeaning, ...distractors]);

    return {
      id: idx,
      word: sw.word,
      options,
      correctAnswerIndex: options.indexOf(correctMeaning)
    };
  });
};

export const generateQuizQuestions = async (date: string, sheetWords?: SheetWord[]): Promise<Question[]> => {
  // CRITICAL: Instantiate inside function to use the most recent process.env.API_KEY
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = "gemini-3-flash-preview";

  if (!sheetWords || sheetWords.length === 0) {
    throw new Error("시험을 생성할 단어 데이터가 없습니다.");
  }

  const shuffled = shuffleArray(sheetWords);
  const limitedWords = shuffled.slice(0, 50); 

  const prompt = `
    I have a vocabulary list for a test. 
    SOURCE DATA: ${JSON.stringify(limitedWords)}

    Task: Create a multiple-choice test based strictly on this source data.

    For each item in the source data:
    1. Use the 'word' as the question.
    2. Use the 'meaning' as the strictly Correct Answer.

    STRICT RULES FOR PREVENTING AMBIGUITY (CRITICAL):
    - Generate 3 distractors that are plausible in terms of part-of-speech but SEMANTICALLY DISTANT from the correct answer.
    - DO NOT use synonyms, near-synonyms, or words with overlapping meanings.
    - Ensure there is absolutely NO overlap in meaning between any of the 4 options.

    3. Randomly shuffle the position of the correct answer among the 4 options.
    4. 'correctAnswerIndex' must point to the correct meaning in the 'options' array.

    Return the result as a JSON array of Question objects.
  `;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.INTEGER },
              word: { type: Type.STRING },
              options: { 
                type: Type.ARRAY, 
                items: { type: Type.STRING },
              },
              correctAnswerIndex: { type: Type.INTEGER }
            },
            required: ["id", "word", "options", "correctAnswerIndex"],
            propertyOrdering: ["id", "word", "options", "correctAnswerIndex"]
          },
        },
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from Gemini");

    return JSON.parse(text) as Question[];

  } catch (error: any) {
    // If the request fails with "Requested entity was not found.", reset key selection and prompt for key selection
    if (error.message?.includes("Requested entity was not found")) {
      const aistudio = (window as any).aistudio;
      if (aistudio && typeof aistudio.openSelectKey === 'function') {
        await aistudio.openSelectKey();
      }
    }

    console.warn("Gemini API Error (likely quota). Falling back to local generation:", error.message);

    if (error.message?.includes("429") || error.message?.includes("quota") || error.message?.includes("limit")) {
      console.info("Using local quiz engine for stability.");
    }

    return generateLocalQuiz(sheetWords);
  }
};

import { SheetWord, QuizResult } from "../types";

// Helper to parse CSV line correctly handling quotes
const parseCSVLine = (line: string): string[] => {
  const result = [];
  let start = 0;
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    if (line[i] === '"') {
      inQuotes = !inQuotes;
    } else if (line[i] === ',' && !inQuotes) {
      result.push(line.substring(start, i).replace(/^"|"$/g, '').replace(/""/g, '"').trim());
      start = i + 1;
    }
  }
  result.push(line.substring(start).replace(/^"|"$/g, '').replace(/""/g, '"').trim());
  return result;
};

export const fetchSheetTabs = async (sheetId: string): Promise<string[]> => {
  const apiKey = process.env.API_KEY;
  const url = `https://sheets.googleapis.com/v4/spreadsheets/${sheetId}?fields=sheets.properties.title&key=${apiKey}`;

  try {
    const response = await fetch(url);

    if (!response.ok) {
      console.warn("Failed to fetch sheet tabs via API. Falling back to manual input.");
      return [];
    }

    const data = await response.json();
    if (data.sheets && Array.isArray(data.sheets)) {
      return data.sheets.map((s: any) => s.properties.title);
    }
    return [];
  } catch (error) {
    console.error("Error fetching sheet tabs:", error);
    return [];
  }
};

export const fetchWordsFromSheet = async (sheetId: string, tabName: string): Promise<SheetWord[]> => {
  const url = `https://docs.google.com/spreadsheets/d/${sheetId}/gviz/tq?tqx=out:csv&sheet=${encodeURIComponent(tabName)}`;

  try {
    const response = await fetch(url);

    if (!response.ok) {
      if (response.status === 404) {
        throw new Error(`Sheet not found. Check ID or Tab Name: ${tabName}`);
      }
      throw new Error(`Failed to fetch sheet. Status: ${response.status}`);
    }

    const text = await response.text();
    const lines = text.split('\n');
    const words: SheetWord[] = [];

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i].trim();
      if (!line) continue;

      const cols = parseCSVLine(line);

      if (cols.length >= 2) {
        const word = cols[0];
        const fullMeaning = cols[1];

        if (word.toLowerCase() === 'word' || word.toLowerCase() === 'english') continue;

        if (word && fullMeaning) {
          // Rule: If multiple meanings exist (comma separated), take only the first one
          const primaryMeaning = fullMeaning.split(',')[0].trim();
          words.push({ word, meaning: primaryMeaning });
        }
      }
    }

    if (words.length === 0) {
      throw new Error("Found the sheet tab, but could not parse any words.");
    }

    return words;

  } catch (error) {
    console.error("Sheet Fetch Error:", error);
    throw error;
  }
};

export const submitResultToSheet = async (scriptUrl: string, result: QuizResult): Promise<boolean> => {
  try {
    const payload = {
      // Changed from result.date to result.className as per teacher's request
      tabName: result.className,
      studentName: result.studentName,
      score: result.score,
      total: result.totalQuestions,
      timeTaken: result.timeTakenSeconds,
      timestamp: result.timestamp,
      testDate: result.date
    };

    await fetch(scriptUrl, {
      method: 'POST',
      mode: 'no-cors', 
      headers: {
        'Content-Type': 'text/plain',
      },
      body: JSON.stringify(payload)
    });

    return true;
  } catch (error) {
    console.error("Failed to submit result:", error);
    return false;
  }
};

