                <div className="flex gap-2">
                  <Button variant="secondary" fullWidth onClick={() => {
                    navigator.clipboard.writeText(shareUrl);
                    setIsCopied(true);
                    setTimeout(() => setIsCopied(false), 2000);
                  }}>
                    {isCopied ? '복사 완료!' : '시험 링크 복사'}
                  </Button>
