          </div>
        </div>
        <div className="flex flex-col sm:flex-row gap-3">
          <Button 
            onClick={handleOpenPaidKeyDialog} 
            fullWidth 
            className="bg-white text-indigo-900 hover:bg-indigo-50 font-black py-4"
          >
            {hasPaidKey ? '연결된 API 키 변경' : '구글 유료 API 키 연결하기'}
