              >
                {isCheckingConnection ? '확인 중...' : connectionStatus === 'success' ? '✅ 연결됨' : connectionStatus === 'fail' ? '❌ 실패' : '연결 확인'}
              </Button>
            </div>

            {showIdGuide && (
