const SHEET_ID_KEY = 'vocamaster_sheet_id';
const SCRIPT_URL_KEY = 'vocamaster_script_url';
const BASE_URL_KEY = 'vocamaster_base_url';

const GAS_CODE_SNIPPET = `/**
 * [연결 테스트용 함수]
 * 브라우저 주소창에 웹 앱 URL을 입력했을 때 이 메시지가 뜨면 정상입니다.
 */
function doGet(e) {
  return ContentService.createTextOutput("VocaMaster 연결 성공! (이 창을 닫으셔도 됩니다)");
}

/**
 * [데이터 저장용 함수]
 * 학생이 시험을 완료하면 이 함수가 실행되어 시트에 저장합니다.
 */
function doPost(e) {
  /*
   * [설치 방법]
   * 1. 구글 시트 상단 메뉴: 확장 프로그램 > Apps Script
   * 2. 기존 코드를 지우고 이 코드를 전체 복사/붙여넣기
   * 3. 우측 상단 [배포] > [새 배포]
   * 4. 톱니바퀴 아이콘 > [웹 앱] 선택
   * 5. 설명: "VocaMaster" (아무거나)
   * 6. 액세스 권한: "모든 사용자" (★중요! 반드시 '모든 사용자'여야 함)
   * 7. [배포] 클릭 -> [승인] -> [URL 복사]
   * 8. 복사한 URL을 VocaMaster 설정창에 붙여넣기
   */

  try {
    var data = JSON.parse(e.postData.contents);
    var ss = SpreadsheetApp.getActiveSpreadsheet();

    // 학생이 선택한 반 이름(탭 이름)으로 시트를 찾습니다.
    var sheetName = data.tabName; 
    var sheet = ss.getSheetByName(sheetName);

    // 만약 해당 반 탭이 없으면 자동으로 생성하고 헤더를 추가합니다.
    if (!sheet) {
      sheet = ss.insertSheet(sheetName);
      sheet.appendRow(["이름", "점수", "총점", "소요시간(초)", "시험날짜", "제출일시"]);
    }

    // 결과 데이터를 마지막 줄에 추가합니다.
    sheet.appendRow([
      data.studentName,
      data.score,
      data.total,
      data.timeTaken,
      data.testDate,
      data.timestamp
    ]);

    return ContentService.createTextOutput("Success").setMimeType(ContentService.MimeType.TEXT);
  } catch(error) {
    return ContentService.createTextOutput("Error: " + error.toString()).setMimeType(ContentService.MimeType.TEXT);
  }
}`;

const TeacherDashboard: React.FC = () => {
  const [sheetId, setSheetId] = useState('');
  const [scriptUrl, setScriptUrl] = useState('');
  const [baseUrl, setBaseUrl] = useState('');
  const [availableTabs, setAvailableTabs] = useState<string[]>([]);
  const [selectedClass, setSelectedClass] = useState('');

  const [isRefreshing, setIsRefreshing] = useState(false);
  const [isCheckingConnection, setIsCheckingConnection] = useState(false);
  // 'success' means tabs loaded via API, 'success_manual' means public access OK but no tabs
  const [connectionStatus, setConnectionStatus] = useState<'none' | 'success' | 'success_manual' | 'fail'>('none');
  const [isCopied, setIsCopied] = useState(false);
  const [hasPaidKey, setHasPaidKey] = useState(false);

  const [showScriptGuide, setShowScriptGuide] = useState(false);
  const [showIdGuide, setShowIdGuide] = useState(false);
  const [isCodeCopied, setIsCodeCopied] = useState(false);

  useEffect(() => {
    // Load initial values from localStorage
    const storedSheetId = localStorage.getItem(SHEET_ID_KEY) || '';
    const storedScriptUrl = localStorage.getItem(SCRIPT_URL_KEY) || '';
    const storedBaseUrl = localStorage.getItem(BASE_URL_KEY) || '';

    setSheetId(storedSheetId);
    setScriptUrl(storedScriptUrl);

    if (storedBaseUrl) {
      setBaseUrl(storedBaseUrl);
    } else {
      const detected = window.location.origin + window.location.pathname;
      setBaseUrl(detected);
      localStorage.setItem(BASE_URL_KEY, detected);
    }

    if (storedSheetId) {
      loadTabs(storedSheetId);
    }

    const aistudio = (window as any).aistudio;
    if (aistudio && typeof aistudio.hasSelectedApiKey === 'function') {
      aistudio.hasSelectedApiKey().then(setHasPaidKey);
    }
  }, []);

  const loadTabs = async (id: string) => {
    if (!id) return;
    setIsRefreshing(true);
    try {
      const tabs = await fetchSheetTabs(id);
      if (tabs.length > 0) {
        setAvailableTabs(tabs);
        setConnectionStatus('success');
      } else {
        // If tabs fail, we just don't populate availableTabs, but we don't necessarily fail the connection yet
        // Check availability strictly if this was a refresh action
        const isAvailable = await checkSheetAvailability(id);
        if (isAvailable) {
           setConnectionStatus('success_manual');
           setAvailableTabs([]);
        }
      }
    } catch (e) { 
      console.error("Tabs loading error", e); 
    } finally {
      setIsRefreshing(false);
    }
  };

  const checkConnection = async () => {
    if (!sheetId) return;
    setIsCheckingConnection(true);
    setConnectionStatus('none');

    try {
      // 1. First try fetching tabs (Best experience)
      const tabs = await fetchSheetTabs(sheetId);
      if (tabs.length > 0) {
        setConnectionStatus('success');
        setAvailableTabs(tabs);
      } else {
        // 2. If API fails, try checking basic public access (Fallback)
        const isAvailable = await checkSheetAvailability(sheetId);
        if (isAvailable) {
          setConnectionStatus('success_manual');
          setAvailableTabs([]);
        } else {
          setConnectionStatus('fail');
        }
      }
    } catch (e) {
      setConnectionStatus('fail');
    } finally {
      setIsCheckingConnection(false);
    }
  };

  const handleSheetIdChange = (val: string) => {
    let cleanId = val.trim();
    // Auto-extract ID if full URL is pasted
    const urlMatch = cleanId.match(/\/d\/([a-zA-Z0-9-_]+)/);
    if (urlMatch) {
      cleanId = urlMatch[1];
    }

    setSheetId(cleanId);
    localStorage.setItem(SHEET_ID_KEY, cleanId);
    setConnectionStatus('none'); // Reset status on change
  };

  const handleScriptUrlChange = (val: string) => {
    setScriptUrl(val.trim());
    localStorage.setItem(SCRIPT_URL_KEY, val.trim());
  };

  const handleBaseUrlChange = (val: string) => {
    setBaseUrl(val.trim());
    localStorage.setItem(BASE_URL_KEY, val.trim());
  };

  const handleOpenPaidKeyDialog = async () => {
    const aistudio = (window as any).aistudio;
    if (aistudio && typeof aistudio.openSelectKey === 'function') {
      await aistudio.openSelectKey();
      setHasPaidKey(true);
    }
  };

  const handleCopyCode = () => {
    navigator.clipboard.writeText(GAS_CODE_SNIPPET);
    setIsCodeCopied(true);
    setTimeout(() => setIsCodeCopied(false), 2000);
  };

  const shareUrl = useMemo(() => {
    if (!sheetId) return "";
    const params = new URLSearchParams();
    params.set('sheet_id', sheetId.trim());
    if (scriptUrl) params.set('script', scriptUrl.trim());
    if (selectedClass) params.set('class_name', selectedClass);
    params.set('date', new Date().toISOString().split('T')[0]);
    const cleanBase = baseUrl.trim() || (window.location.origin + window.location.pathname);
    const connector = cleanBase.includes('?') ? '&' : '?';
    return `${cleanBase}${connector}${params.toString()}`;
  }, [sheetId, scriptUrl, selectedClass, baseUrl]);

  const qrUrl = useMemo(() => {
    if (!shareUrl) return "";
    return `https://quickchart.io/qr?text=${encodeURIComponent(shareUrl)}&size=400&margin=2&ecLevel=H`;
  }, [shareUrl]);

  const isInvalidUrl = useMemo(() => {
    const lower = baseUrl.toLowerCase();
    return lower.includes('vercel.com') && !lower.includes('vercel.app');
  }, [baseUrl]);

  const isScriptUrlWarning = useMemo(() => {
    if (!scriptUrl) return false;
    // Check for common mistakes
    if (scriptUrl.includes('/edit')) return true;
    if (scriptUrl.includes('/dev')) return true;
    if (!scriptUrl.endsWith('/exec')) return true;
    return false;
  }, [scriptUrl]);

  return (
    <div className="animate-pop space-y-8 pb-24">
      <div className="text-center mb-2">
        <h2 className="text-3xl font-black text-indigo-900 tracking-tight">선생님 관리 센터</h2>
