      </section>

      {/* 2. AI Quota Management */}
      <section className="bg-gradient-to-br from-indigo-900 to-indigo-800 rounded-[2.5rem] shadow-xl p-8 text-white">
        <div className="flex justify-between items-start mb-6">
          <div>
            <h3 className="text-xl font-black mb-1">AI 사용량(Quota) 관리</h3>
            <p className="text-indigo-200 text-xs">429(Too Many Requests) 에러 발생 시 유료 키를 연결하세요.</p>
          </div>
          <div className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${hasPaidKey ? 'bg-green-500' : 'bg-amber-500'}`}>
            {hasPaidKey ? '유료 키 활성화됨' : '무료 티어 사용 중'}
