        <div className="flex justify-between items-center mb-8">
          <h3 className="text-xl font-black text-indigo-900">⚙️ 시스템 설정 (자동 저장)</h3>
          <span className="text-[10px] font-black text-green-600 bg-green-50 px-2 py-1 rounded-md uppercase tracking-widest">Real-time Sync</span>
        </div>
        <div className="space-y-6">
          <div className="space-y-2">
            <div className="flex justify-between items-center">
              <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest">구글 시트 ID (또는 주소 전체)</label>
              <button 
                onClick={() => setShowIdGuide(!showIdGuide)}
                className="text-[10px] text-indigo-600 font-bold hover:underline"
              >
                {showIdGuide ? '가이드 닫기' : '❓ 시트 ID가 무엇인가요?'}
              </button>
            </div>

            <div className="flex gap-2">
              <input 
                type="text" 
                value={sheetId}
                onChange={(e) => handleSheetIdChange(e.target.value)}
