            <input 
              type="text" 
              value={scriptUrl}
              onChange={(e) => handleScriptUrlChange(e.target.value)}
              className={`w-full px-5 py-4 border-2 rounded-2xl font-mono text-sm focus:bg-white outline-none transition-all ${isScriptUrlWarning ? 'border-red-300 bg-red-50 text-red-900 focus:border-red-500' : 'border-gray-100 bg-gray-50/50 focus:border-indigo-300'}`}
              placeholder="https://script.google.com/macros/s/.../exec"
            />
            {isScriptUrlWarning && (
              <p className="text-[10px] text-red-500 font-bold mt-1">
                ⚠️ 주소가 '/exec'로 끝나야 합니다. '/edit'나 '/dev' 주소는 작동하지 않습니다.
              </p>
            )}
          </div>

          {/* Apps Script Guide Modal/Section */}
          {showScriptGuide && (
            <div className="bg-gray-800 rounded-2xl p-6 text-white animate-pop border-2 border-indigo-500/30">
              <div className="flex justify-between items-center mb-4">
                <h4 className="font-bold text-lg text-green-400">Apps Script 자동 저장 설정 가이드</h4>
                <button 
                  onClick={handleCopyCode}
                  className={`text-xs px-3 py-1 rounded-lg font-bold transition-all ${isCodeCopied ? 'bg-green-500 text-white' : 'bg-white text-gray-900'}`}
                >
                  {isCodeCopied ? '복사 완료!' : '코드 전체 복사'}
                </button>
              </div>

              {/* Troubleshooting Box */}
              <div className="bg-red-500/20 border border-red-500/50 rounded-xl p-4 mb-4">
                <h5 className="font-bold text-red-200 text-xs mb-1">⚠️ "script.google.com에서 리디렉션 횟수 초과" 오류가 뜨나요?</h5>
                <p className="text-[11px] text-gray-300 leading-relaxed">
                  구글 계정이 여러 개 로그인되어 있으면 충돌이 발생합니다.<br/>
                  <span className="text-white font-bold underline">시크릿 창(Incognito)</span>을 열어서 Apps Script에 접속해보세요. (단축키: Ctrl+Shift+N)
                </p>
              </div>

              <p className="text-xs text-gray-400 mb-4 leading-relaxed">
                1. 구글 시트 메뉴 [확장 프로그램] &gt; [Apps Script] 클릭<br/>
                2. 기존 코드를 모두 지우고 아래 코드를 붙여넣으세요.<br/>
                3. 우측 상단 [배포] &gt; [새 배포] &gt; [웹 앱]<br/>
                4. <strong className="text-yellow-400">액세스 권한: '모든 사용자' (필수)</strong>로 설정하고 배포.<br/>
                5. 생성된 '웹 앱 URL'을 위 칸에 입력하세요.
              </p>
              <pre className="bg-gray-900 p-4 rounded-xl text-[10px] font-mono overflow-x-auto border border-gray-700 text-gray-300 leading-normal">
                {GAS_CODE_SNIPPET}
              </pre>
            </div>
          )}

          <div className="bg-amber-50 p-6 rounded-3xl border-2 border-amber-100 space-y-3">
            <div className="flex justify-between items-center">
              <label className="text-[10px] font-black text-amber-900 uppercase tracking-widest">학생 접속 주소 (Base URL)</label>
              <button 
                onClick={() => {
                  const detected = window.location.origin + window.location.pathname;
                  handleBaseUrlChange(detected);
                }} 
                className="text-[10px] bg-amber-200 px-2 py-1 rounded-lg font-bold hover:bg-amber-300"
              >
                현재 주소로 초기화
              </button>
            </div>
            <input 
              type="text" 
              value={baseUrl}
              onChange={(e) => handleBaseUrlChange(e.target.value)}
              className={`w-full px-5 py-4 border-2 rounded-2xl font-mono text-sm outline-none transition-all ${isInvalidUrl ? 'border-red-400 bg-red-50 text-red-900' : 'border-amber-200 bg-white'}`}
            />
            {isInvalidUrl && <p className="text-[10px] text-red-500 font-bold">⚠️ Vercel 미리보기 URL은 배포용으로 적합하지 않습니다. 실제 도메인 주소를 입력하세요.</p>}
          </div>

          <div className="pt-2">
             <Button 
               fullWidth 
               variant="ghost"
               onClick={() => loadTabs(sheetId)}
               className="text-gray-400 text-xs font-bold"
             >
               데이터 다시 불러오기 (수동 동기화)
             </Button>
          </div>
        </div>
      </section>
    </div>
  );
};

export default TeacherDashboard;

import React, { useEffect, useState, useMemo } from 'react';
import Button from '../components/Button';
import { fetchSheetTabs, checkSheetAvailability } from '../services/sheetService';

const SHEET_ID_KEY = 'vocamaster_sheet_id';
const SCRIPT_URL_KEY = 'vocamaster_script_url';
const BASE_URL_KEY = 'vocamaster_base_url';

const GAS_CODE_SNIPPET = `/**
 * [연결 테스트용 함수]
 * 브라우저 주소창에 웹 앱 URL을 입력했을 때 이 메시지가 뜨면 정상입니다.
 */
function doGet(e) {
  return ContentService.createTextOutput("VocaMaster 연결 성공! (이 창을 닫으셔도 됩니다)");
}

/**
 * [데이터 저장용 함수]
 * 학생이 시험을 완료하면 이 함수가 실행되어 시트에 저장합니다.
 */
function doPost(e) {
  /*
   * [설치 방법]
   * 1. 구글 시트 상단 메뉴: 확장 프로그램 > Apps Script
   * 2. 기존 코드를 지우고 이 코드를 전체 복사/붙여넣기
   * 3. 우측 상단 [배포] > [새 배포]
   * 4. 톱니바퀴 아이콘 > [웹 앱] 선택
   * 5. 설명: "VocaMaster" (아무거나)
   * 6. 액세스 권한: "모든 사용자" (★중요! 반드시 '모든 사용자'여야 함)
   * 7. [배포] 클릭 -> [승인] -> [URL 복사]
   * 8. 복사한 URL을 VocaMaster 설정창에 붙여넣기
   */

  try {
    var data = JSON.parse(e.postData.contents);
    var ss = SpreadsheetApp.getActiveSpreadsheet();

    // 학생이 선택한 반 이름(탭 이름)으로 시트를 찾습니다.
    var sheetName = data.tabName; 
    var sheet = ss.getSheetByName(sheetName);

    // 만약 해당 반 탭이 없으면 자동으로 생성하고 헤더를 추가합니다.
    if (!sheet) {
      sheet = ss.insertSheet(sheetName);
      sheet.appendRow(["이름", "점수", "총점", "소요시간(초)", "시험날짜", "제출일시"]);
    }

    // 결과 데이터를 마지막 줄에 추가합니다.
    sheet.appendRow([
      data.studentName,
      data.score,
      data.total,
      data.timeTaken,
      data.testDate,
      data.timestamp
    ]);

    return ContentService.createTextOutput("Success").setMimeType(ContentService.MimeType.TEXT);
  } catch(error) {
    return ContentService.createTextOutput("Error: " + error.toString()).setMimeType(ContentService.MimeType.TEXT);
  }
}`;

const TeacherDashboard: React.FC = () => {
  const [sheetId, setSheetId] = useState('');
  const [scriptUrl, setScriptUrl] = useState('');
  const [baseUrl, setBaseUrl] = useState('');
  const [availableTabs, setAvailableTabs] = useState<string[]>([]);
  const [selectedClass, setSelectedClass] = useState('');

  const [isRefreshing, setIsRefreshing] = useState(false);
  const [isCheckingConnection, setIsCheckingConnection] = useState(false);
  // 'success' means tabs loaded via API, 'success_manual' means public access OK but no tabs
  const [connectionStatus, setConnectionStatus] = useState<'none' | 'success' | 'success_manual' | 'fail'>('none');
  const [isCopied, setIsCopied] = useState(false);
  const [hasPaidKey, setHasPaidKey] = useState(false);

  const [showScriptGuide, setShowScriptGuide] = useState(false);
  const [showIdGuide, setShowIdGuide] = useState(false);
  const [isCodeCopied, setIsCodeCopied] = useState(false);

  useEffect(() => {
    // Load initial values from localStorage
    const storedSheetId = localStorage.getItem(SHEET_ID_KEY) || '';
    const storedScriptUrl = localStorage.getItem(SCRIPT_URL_KEY) || '';
    const storedBaseUrl = localStorage.getItem(BASE_URL_KEY) || '';

    setSheetId(storedSheetId);
    setScriptUrl(storedScriptUrl);

    if (storedBaseUrl) {
      setBaseUrl(storedBaseUrl);
    } else {
      const detected = window.location.origin + window.location.pathname;
      setBaseUrl(detected);
      localStorage.setItem(BASE_URL_KEY, detected);
    }

    if (storedSheetId) {
      loadTabs(storedSheetId);
    }

    const aistudio = (window as any).aistudio;
    if (aistudio && typeof aistudio.hasSelectedApiKey === 'function') {
      aistudio.hasSelectedApiKey().then(setHasPaidKey);
    }
  }, []);

  const loadTabs = async (id: string) => {
    if (!id) return;
    setIsRefreshing(true);
    try {
      const tabs = await fetchSheetTabs(id);
      if (tabs.length > 0) {
        setAvailableTabs(tabs);
        setConnectionStatus('success');
      } else {
        // If tabs fail, we just don't populate availableTabs, but we don't necessarily fail the connection yet
        // Check availability strictly if this was a refresh action
        const isAvailable = await checkSheetAvailability(id);
        if (isAvailable) {
           setConnectionStatus('success_manual');
           setAvailableTabs([]);
        }
      }
    } catch (e) { 
      console.error("Tabs loading error", e); 
    } finally {
      setIsRefreshing(false);
    }
  };

  const checkConnection = async () => {
    if (!sheetId) return;
    setIsCheckingConnection(true);
    setConnectionStatus('none');

    try {
      // 1. First try fetching tabs (Best experience)
      const tabs = await fetchSheetTabs(sheetId);
      if (tabs.length > 0) {
        setConnectionStatus('success');
        setAvailableTabs(tabs);
      } else {
        // 2. If API fails, try checking basic public access (Fallback)
        const isAvailable = await checkSheetAvailability(sheetId);
        if (isAvailable) {
          setConnectionStatus('success_manual');
          setAvailableTabs([]);
        } else {
          setConnectionStatus('fail');
        }
      }
    } catch (e) {
      setConnectionStatus('fail');
    } finally {
      setIsCheckingConnection(false);
    }
  };

  const handleSheetIdChange = (val: string) => {
    let cleanId = val.trim();
    // Auto-extract ID if full URL is pasted
    const urlMatch = cleanId.match(/\/d\/([a-zA-Z0-9-_]+)/);
    if (urlMatch) {
      cleanId = urlMatch[1];
    }

    setSheetId(cleanId);
    localStorage.setItem(SHEET_ID_KEY, cleanId);
    setConnectionStatus('none'); // Reset status on change
  };

  const handleScriptUrlChange = (val: string) => {
    setScriptUrl(val.trim());
    localStorage.setItem(SCRIPT_URL_KEY, val.trim());
  };

  const handleBaseUrlChange = (val: string) => {
    setBaseUrl(val.trim());
    localStorage.setItem(BASE_URL_KEY, val.trim());
  };

  const handleOpenPaidKeyDialog = async () => {
    const aistudio = (window as any).aistudio;
    if (aistudio && typeof aistudio.openSelectKey === 'function') {
      await aistudio.openSelectKey();
      setHasPaidKey(true);
    }
  };

  const handleCopyCode = () => {
    navigator.clipboard.writeText(GAS_CODE_SNIPPET);
    setIsCodeCopied(true);
    setTimeout(() => setIsCodeCopied(false), 2000);
  };

  const isMalformedBaseUrl = useMemo(() => {
    if (!baseUrl) return false;
    // Check for "googhttps" which was the error, or simply not starting with http
    return baseUrl.includes('googhttps') || !baseUrl.startsWith('http');
  }, [baseUrl]);

  const shareUrl = useMemo(() => {
    if (!sheetId) return "";
    const params = new URLSearchParams();
    params.set('sheet_id', sheetId.trim());
    if (scriptUrl) params.set('script', scriptUrl.trim());
    if (selectedClass) params.set('class_name', selectedClass);
    params.set('date', new Date().toISOString().split('T')[0]);

    // Always fallback to window.location if baseUrl is empty, but if it's explicitly set to garbage, that's the problem.
    // We should trust the user input generally, but if it's clearly broken (isMalformedBaseUrl), we might want to warn or just use it (so they see it's broken).
    // Here, we use the input value so the QR reflects the error until they fix it.
    const cleanBase = baseUrl.trim() || (window.location.origin + window.location.pathname);
    const connector = cleanBase.includes('?') ? '&' : '?';
    return `${cleanBase}${connector}${params.toString()}`;
  }, [sheetId, scriptUrl, selectedClass, baseUrl]);

  const qrUrl = useMemo(() => {
    if (!shareUrl) return "";
    return `https://quickchart.io/qr?text=${encodeURIComponent(shareUrl)}&size=400&margin=2&ecLevel=H`;
  }, [shareUrl]);

  const isInvalidUrl = useMemo(() => {
    const lower = baseUrl.toLowerCase();
    return lower.includes('vercel.com') && !lower.includes('vercel.app');
  }, [baseUrl]);

  const isScriptUrlWarning = useMemo(() => {
    if (!scriptUrl) return false;
    // Check for common mistakes
    if (scriptUrl.includes('/edit')) return true;
    if (scriptUrl.includes('/dev')) return true;
    if (!scriptUrl.endsWith('/exec')) return true;
    return false;
  }, [scriptUrl]);

  return (
    <div className="animate-pop space-y-8 pb-24">
      <div className="text-center mb-2">
        <h2 className="text-3xl font-black text-indigo-900 tracking-tight">선생님 관리 센터</h2>
        <p className="text-gray-500 text-sm mt-1">모든 설정은 입력 시 실시간으로 저장됩니다.</p>
      </div>

      {/* 1. Deployment Section (Integrated QR) */}
      <section className="bg-white rounded-[2.5rem] shadow-xl border-2 border-indigo-50 overflow-hidden">
        <div className="bg-indigo-600 px-8 py-6 text-white flex justify-between items-center">
          <div>
            <h3 className="text-xl font-black">🚀 학생 시험 배포</h3>
            <p className="text-indigo-100 text-xs opacity-80">설정된 정보로 생성된 실시간 QR코드입니다.</p>
          </div>
          {sheetId && (
            <button 
              onClick={() => loadTabs(sheetId)}
              disabled={isRefreshing}
              className="bg-white/20 hover:bg-white/30 p-2 rounded-xl transition-all"
              title="반 목록 새로고침"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className={`h-5 w-5 ${isRefreshing ? 'animate-spin' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
