          )}

          <div className={`p-6 rounded-3xl border-2 space-y-3 ${isMalformedBaseUrl ? 'bg-red-50 border-red-200' : 'bg-amber-50 border-amber-100'}`}>
            <div className="flex justify-between items-center">
              <label className={`text-[10px] font-black uppercase tracking-widest ${isMalformedBaseUrl ? 'text-red-600' : 'text-amber-900'}`}>
