import React, { useEffect, useState, useMemo } from 'react';
import Button from '../components/Button.tsx';
import { fetchSheetTabs, checkSheetAvailability } from '../services/sheetService.ts';

const SHEET_ID_KEY = 'vocamaster_sheet_id';
const SCRIPT_URL_KEY = 'vocamaster_script_url';
const BASE_URL_KEY = 'vocamaster_base_url';

const GAS_CODE_SNIPPET = `/**
 * [VocaMaster 전용 Apps Script 코드]
 * 아래 코드를 복사하여 Google Apps Script에 붙여넣으세요.
 */

function doGet(e) {
  return ContentService.createTextOutput("VocaMaster 연결 성공! (이 창을 닫으셔도 됩니다)");
}

function doPost(e) {
  try {
    var data = JSON.parse(e.postData.contents);
    var ss = SpreadsheetApp.getActiveSpreadsheet();

    // 학생이 선택한 반 이름(탭 이름)으로 시트를 찾습니다.
    var sheetName = data.tabName || "전체결과"; 
    var sheet = ss.getSheetByName(sheetName);

    // 시트가 없으면 생성
    if (!sheet) {
      sheet = ss.insertSheet(sheetName);
      sheet.appendRow(["이름", "점수", "총점", "소요시간(초)", "시험날짜", "제출일시"]);
    }

    // 데이터 추가
    sheet.appendRow([
      data.studentName,
      data.score,
      data.total,
      data.timeTaken,
      data.testDate,
      data.timestamp
    ]);

    return ContentService.createTextOutput("Success").setMimeType(ContentService.MimeType.TEXT);
  } catch(error) {
    return ContentService.createTextOutput("Error: " + error.toString()).setMimeType(ContentService.MimeType.TEXT);
  }
}`;

const TeacherDashboard: React.FC = () => {
  const [sheetId, setSheetId] = useState('');
  const [scriptUrl, setScriptUrl] = useState('');
  const [baseUrl, setBaseUrl] = useState('');
  const [availableTabs, setAvailableTabs] = useState<string[]>([]);
  const [selectedClass, setSelectedClass] = useState('');

  const [isRefreshing, setIsRefreshing] = useState(false);
  const [isCheckingConnection, setIsCheckingConnection] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState<'none' | 'success' | 'success_manual' | 'fail'>('none');
  const [isCopied, setIsCopied] = useState(false);
  const [hasPaidKey, setHasPaidKey] = useState(false);

  const [showScriptGuide, setShowScriptGuide] = useState(false);
  const [showIdGuide, setShowIdGuide] = useState(false);
  const [isCodeCopied, setIsCodeCopied] = useState(false);

  useEffect(() => {
    const storedSheetId = localStorage.getItem(SHEET_ID_KEY) || '';
    const storedScriptUrl = localStorage.getItem(SCRIPT_URL_KEY) || '';
    const storedBaseUrl = localStorage.getItem(BASE_URL_KEY) || '';

    setSheetId(storedSheetId);
    setScriptUrl(storedScriptUrl);

    if (storedBaseUrl && !storedBaseUrl.includes('googhttps')) {
      setBaseUrl(storedBaseUrl);
    } else {
      const detected = window.location.origin + window.location.pathname;
      setBaseUrl(detected);
      localStorage.setItem(BASE_URL_KEY, detected);
    }

    if (storedSheetId) {
      loadTabs(storedSheetId);
    }

    const aistudio = (window as any).aistudio;
    if (aistudio && typeof aistudio.hasSelectedApiKey === 'function') {
      aistudio.hasSelectedApiKey().then(setHasPaidKey);
    }
  }, []);

  const loadTabs = async (id: string) => {
    if (!id) return;
    setIsRefreshing(true);
    try {
      const tabs = await fetchSheetTabs(id);
      if (tabs.length > 0) {
        setAvailableTabs(tabs);
        setConnectionStatus('success');
      } else {
        const isAvailable = await checkSheetAvailability(id);
        if (isAvailable) {
           setConnectionStatus('success_manual');
           setAvailableTabs([]);
        }
      }
    } catch (e) { 
      console.error("Tabs loading error", e); 
    } finally {
      setIsRefreshing(false);
    }
  };

  const checkConnection = async () => {
    if (!sheetId) return;
    setIsCheckingConnection(true);
    setConnectionStatus('none');
    try {
      const tabs = await fetchSheetTabs(sheetId);
      if (tabs.length > 0) {
        setConnectionStatus('success');
        setAvailableTabs(tabs);
      } else {
        const isAvailable = await checkSheetAvailability(sheetId);
        if (isAvailable) {
          setConnectionStatus('success_manual');
          setAvailableTabs([]);
        } else {
          setConnectionStatus('fail');
        }
      }
    } catch (e) {
      setConnectionStatus('fail');
    } finally {
      setIsCheckingConnection(false);
    }
  };

  const handleSheetIdChange = (val: string) => {
    let cleanId = val.trim();
    const urlMatch = cleanId.match(/\/d\/([a-zA-Z0-9-_]+)/);
    if (urlMatch) cleanId = urlMatch[1];
    setSheetId(cleanId);
    localStorage.setItem(SHEET_ID_KEY, cleanId);
    setConnectionStatus('none');
  };

  const handleScriptUrlChange = (val: string) => {
    setScriptUrl(val.trim());
    localStorage.setItem(SCRIPT_URL_KEY, val.trim());
  };

  const handleBaseUrlChange = (val: string) => {
    setBaseUrl(val.trim());
    localStorage.setItem(BASE_URL_KEY, val.trim());
  };

  const handleCopyCode = () => {
    navigator.clipboard.writeText(GAS_CODE_SNIPPET);
    setIsCodeCopied(true);
    setTimeout(() => setIsCodeCopied(false), 2000);
  };

  const isMalformedBaseUrl = useMemo(() => {
    if (!baseUrl) return false;
    return baseUrl.includes('googhttps') || !baseUrl.startsWith('http');
  }, [baseUrl]);

  const isMalformedScriptUrl = useMemo(() => {
    if (!scriptUrl) return false;
    return scriptUrl.includes('googhttps') || (scriptUrl.match(/https/g) || []).length > 1;
  }, [scriptUrl]);

  const shareUrl = useMemo(() => {
    if (!sheetId) return "";
    const params = new URLSearchParams();
    params.set('sheet_id', sheetId.trim());
    if (scriptUrl) params.set('script', scriptUrl.trim());
    if (selectedClass) params.set('class_name', selectedClass);
    params.set('date', new Date().toISOString().split('T')[0]);
    const cleanBase = baseUrl.trim() || (window.location.origin + window.location.pathname);
    const connector = cleanBase.includes('?') ? '&' : '?';
    return `${cleanBase}${connector}${params.toString()}`;
  }, [sheetId, scriptUrl, selectedClass, baseUrl]);

  const qrUrl = useMemo(() => {
    if (!shareUrl) return "";
    return `https://quickchart.io/qr?text=${encodeURIComponent(shareUrl)}&size=400&margin=2&ecLevel=H`;
  }, [shareUrl]);

  return (
    <div className="animate-pop space-y-8 pb-24">
      <div className="text-center mb-2">
        <h2 className="text-3xl font-black text-indigo-900 tracking-tight">선생님 관리 센터</h2>
        <p className="text-gray-500 text-sm mt-1">설정이 올바른지 확인해주세요.</p>
      </div>

      <section className="bg-white rounded-[2.5rem] shadow-xl border-2 border-indigo-50 overflow-hidden">
        <div className="bg-indigo-600 px-8 py-6 text-white flex justify-between items-center">
          <div>
            <h3 className="text-xl font-black">🚀 학생 시험 배포 (QR)</h3>
          </div>
          {sheetId && (
            <button onClick={() => loadTabs(sheetId)} className="bg-white/20 p-2 rounded-xl">
              <svg xmlns="http://www.w3.org/2000/svg" className={`h-5 w-5 ${isRefreshing ? 'animate-spin' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
              </svg>
            </button>
          )}
        </div>

        <div className="p-8 grid grid-cols-1 md:grid-cols-2 gap-10 items-center">
          <div className="space-y-6">
            <div className="bg-indigo-50 p-6 rounded-3xl border border-indigo-100">
              <label className="block text-[10px] font-black text-indigo-400 uppercase mb-3 tracking-widest">배포할 수업반 선택</label>
              <select value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)} className="w-full px-4 py-4 border-2 border-indigo-200 rounded-2xl font-bold mb-4">
                <option value="">-- 반 선택 --</option>
                {availableTabs.map(tab => <option key={tab} value={tab}>{tab}</option>)}
              </select>
              <div className="flex gap-2">
                <Button variant="secondary" fullWidth onClick={() => {
                  navigator.clipboard.writeText(shareUrl);
                  setIsCopied(true);
                  setTimeout(() => setIsCopied(false), 2000);
                }}>{isCopied ? '복사 완료!' : '시험 링크 복사'}</Button>
                <a href={shareUrl} target="_blank" className="px-6 py-3 bg-indigo-900 text-white rounded-xl text-xs font-bold flex items-center">열기</a>
              </div>
            </div>
          </div>
          <div className="flex flex-col items-center justify-center p-6 bg-gray-50 rounded-[2rem] border-2 border-dashed border-gray-200">
            <img src={qrUrl} alt="QR" className="w-48 h-48 mb-3 shadow-sm rounded-lg" />
            <span className="text-[10px] font-black text-gray-400 uppercase">Scan to Start Quiz</span>
          </div>
        </div>
      </section>

      <section className="bg-white rounded-[2.5rem] shadow-xl border-2 border-indigo-50 p-8 space-y-8">
        <h3 className="text-xl font-black text-indigo-900">⚙️ 시스템 설정</h3>

        <div className={`p-5 rounded-2xl border-2 ${isMalformedScriptUrl ? 'bg-red-50 border-red-500' : 'bg-gray-50 border-gray-100'}`}>
          <div className="flex justify-between items-center mb-3">
            <label className="text-xs font-black text-gray-500">Apps Script URL (자동 저장)</label>
            <div className="flex gap-2">
              <button onClick={() => setShowScriptGuide(!showScriptGuide)} className="text-xs font-bold text-indigo-600 underline">설정 가이드</button>
              {isMalformedScriptUrl && (
                <button onClick={() => handleScriptUrlChange('')} className="bg-red-600 text-white px-3 py-1 rounded-lg text-xs font-bold animate-pulse">지우고 새로 입력</button>
              )}
            </div>
          </div>
          <input type="text" value={scriptUrl} onChange={(e) => handleScriptUrlChange(e.target.value)} className="w-full px-5 py-4 border-2 rounded-2xl font-mono text-sm outline-none" placeholder="https://script.google.com/macros/s/.../exec" />
          {isMalformedScriptUrl && <p className="text-xs text-red-600 font-bold mt-2">🚨 오타(googhttps 등)가 감지되었습니다. 위 버튼을 눌러 지우고 다시 입력하세요.</p>}
        </div>

        {showScriptGuide && (
          <div className="bg-gray-800 rounded-2xl p-6 text-white animate-pop">
            <div className="flex justify-between items-center mb-4">
              <h4 className="font-bold text-green-400">Apps Script 코드</h4>
              <button onClick={handleCopyCode} className="text-xs px-3 py-1 bg-white text-black rounded-lg font-bold">{isCodeCopied ? '복사됨!' : '코드 복사'}</button>
            </div>
            <pre className="text-[10px] font-mono text-gray-400 overflow-x-auto bg-gray-900 p-4 rounded-xl">{GAS_CODE_SNIPPET}</pre>
          </div>
        )}

        <div className={`p-5 rounded-2xl border-2 ${isMalformedBaseUrl ? 'bg-red-50 border-red-500' : 'bg-gray-50 border-gray-100'}`}>
          <div className="flex justify-between items-center mb-3">
            <label className="text-xs font-black text-gray-500">학생 접속 주소 (Base URL)</label>
            <button onClick={() => {
              const detected = window.location.origin + window.location.pathname;
              handleBaseUrlChange(detected);
            }} className="bg-indigo-600 text-white px-3 py-2 rounded-lg text-xs font-bold">현재 주소로 강제 고치기</button>
          </div>
          <input type="text" value={baseUrl} onChange={(e) => handleBaseUrlChange(e.target.value)} className="w-full px-5 py-4 border-2 rounded-2xl font-mono text-sm outline-none" />
          {isMalformedBaseUrl && <p className="text-xs text-red-600 font-bold mt-2">🚨 주소가 잘못되었습니다. '강제 고치기' 버튼을 눌러주세요.</p>}
        </div>
      </section>
    </div>
  );
};

