                  setTimeout(() => setIsCopied(false), 2000);
                }}>{isCopied ? '복사 완료!' : '시험 링크 복사'}</Button>
                <a href={shareUrl} target="_blank" className="px-6 py-3 bg-indigo-900 text-white rounded-xl text-xs font-bold flex items-center">열기</a>
              </div>
            </div>
          </div>
          <div className="flex flex-col items-center justify-center p-6 bg-gray-50 rounded-[2rem] border-2 border-dashed border-gray-200">
            <img src={qrUrl} alt="QR" className="w-48 h-48 mb-3 shadow-sm rounded-lg" />
            <span className="text-[10px] font-black text-gray-400 uppercase">Scan to Start Quiz</span>
          </div>
        </div>
      </section>

      <section className="bg-white rounded-[2.5rem] shadow-xl border-2 border-indigo-50 p-8 space-y-8">
