 * 6. [배포] 클릭 -> [승인] -> URL 복사
 * ---------------------------------------------------------
 * [주의] 이 함수를 에디터에서 직접 '▷ 실행' 누르면 오류가 날 수 있습니다.
 * 이것은 웹사이트에서 시험을 제출할 때 자동으로 작동하는 코드입니다.
 */

function doGet(e) {
  // 연결 테스트용
  return ContentService.createTextOutput("VocaMaster 연결 성공! (설정이 완료되었습니다)");
}

function doPost(e) {
