const sanitizeInput = (val: string) => {
  if (!val) return '';
  let clean = val.trim();
  // Remove common copy-paste garbage
  clean = clean.replace(/\\$/, ''); 
  clean = clean.replace(/googhttps?$/, '');
  clean = clean.replace(/googhtt$/, '');
  return clean;
};

