          )}
        </div>

        {/* 2-3. 배포 주소 설정 */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 transition-all hover:shadow-md">
           <div className="flex justify-between items-start mb-4">
             <div>
               <label className="text-sm font-bold text-gray-700 block mb-1">3. 학생 접속 기본 주소 (Base URL)</label>
               <p className="text-xs text-gray-400">QR코드 생성 시 사용되는 이 사이트의 주소입니다.</p>
             </div>
             <button 
               onClick={() => handleBaseUrlChange(window.location.origin + window.location.pathname)}
               className="text-xs bg-gray-100 hover:bg-gray-200 text-gray-600 px-3 py-1.5 rounded-lg font-bold transition-colors"
             >
               현재 주소 자동 입력
             </button>
           </div>
           <input 
              type="text" 
              value={baseUrl} 
              onChange={(e) => handleBaseUrlChange(e.target.value)} 
              className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-mono text-gray-500"
            />
        </div>
      </div>
    </div>
  );
};

