                <path strokeLinecap="round" strokeLinejoin="round" d="M12 6.042A8.967 8.967 0 006 3.75c-1.052 0-2.062.18-3 .512v14.25A8.987 8.987 0 016 18c2.305 0 4.408.867 6 2.292m0-14.25a8.966 8.966 0 016-2.292c1.052 0 2.062.18 3 .512v14.25A8.987 8.987 0 0018 18a8.967 8.967 0 00-6 2.292m0-14.25v14.25" />
              </svg>
            </div>
            <h1 className="text-xl font-bold text-gray-800 tracking-tight">PIF영어학원</h1>
          </div>

          {currentView === AppView.LANDING && (
             <div className="flex gap-4">
                <button 
                  onClick={() => setCurrentView(AppView.TEACHER_LOGIN)}
                  className="px-4 py-2 rounded-md bg-gray-100 hover:bg-gray-200 text-gray-700 font-medium text-sm transition-colors"
                >
                  선생님
                </button>
             </div>
          )}
          {(currentView === AppView.TEACHER_DASHBOARD || currentView === AppView.INCORRECT_NOTE || currentView === AppView.TEACHER_LOGIN) && (
             <button 
               onClick={handleLogout}
               className="text-sm text-gray-500 hover:text-red-600 font-medium transition-colors"
             >
               닫기
             </button>
          )}
        </div>
      </header>

      <main className="max-w-4xl mx-auto px-4 py-8">
        {isLoading ? (
          <div className="flex flex-col items-center justify-center h-96 animate-pop text-center">
             <div className="w-16 h-16 border-4 border-indigo-200 border-t-indigo-600 rounded-full animate-spin mb-6"></div>
             <p className="text-lg text-gray-600 font-semibold px-4">{loadingMessage}</p>
             <p className="text-sm text-gray-400 mt-2">안정적인 시험 환경을 구성하고 있습니다...</p>
          </div>
        ) : (
          <>
            {currentView === AppView.LANDING && (
              <Landing 
                onStart={handleStartQuiz} 
                onChangeView={setCurrentView}
              />
            )}

            {currentView === AppView.QUIZ && (
              <Quiz 
                questions={questions} 
                onComplete={handleQuizComplete} 
              />
            )}

            {currentView === AppView.RESULT && lastResult && (
              <Result 
                result={lastResult} 
                onHome={handleLogout} 
                submissionStatus={submissionStatus}
              />
            )}

            {currentView === AppView.INCORRECT_NOTE && (
              <IncorrectNote 
                initialStudentName={session?.name}
                incorrectRecords={incorrectRecords}
                onStartReview={(qs, name) => handleStartReview(qs, name)}
                onBack={() => setCurrentView(AppView.LANDING)}
              />
            )}

            {currentView === AppView.TEACHER_LOGIN && (
              <div className="max-w-md mx-auto bg-white p-8 rounded-2xl shadow-lg border border-gray-100 animate-pop">
                <h2 className="text-2xl font-bold mb-6 text-center">선생님 로그인</h2>
                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">액세스 코드</label>
                    <input 
                      type="password" 
                      value={accessCode}
                      onChange={(e) => setAccessCode(e.target.value)}
                      onKeyDown={(e) => e.key === 'Enter' && handleLogin()}
                      className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
                      placeholder="비밀번호 입력"
                    />
                    {loginError && <p className="text-red-500 text-sm mt-1">{loginError}</p>}
                  </div>
                  <button 
                    onClick={handleLogin}
                    className="w-full bg-gray-900 text-white py-2 rounded-lg hover:bg-black transition-colors"
                  >
                    대시보드 입장
                  </button>
                  <button 
                    onClick={() => setCurrentView(AppView.LANDING)}
                    className="w-full text-gray-500 py-2 text-sm hover:text-gray-700"
                  >
                    취소
                  </button>
                </div>
              </div>
            )}

            {currentView === AppView.TEACHER_DASHBOARD && (
              <TeacherDashboard />
            )}
          </>
        )}
      </main>
    </div>
  );
}

export default App;

import React, { useEffect, useState, useMemo } from 'react';
import Button from '../components/Button';
import { fetchSheetTabs, checkSheetAvailability } from '../services/sheetService';

const SHEET_ID_KEY = 'vocamaster_sheet_id';
const SCRIPT_URL_KEY = 'vocamaster_script_url';
const BASE_URL_KEY = 'vocamaster_base_url';

// Deployment Version Indicator
const APP_VERSION = "v1.5 (Build Fix)";
// User's Vercel Domain
const PRESET_DOMAIN = "https://voca-git-main-aiden8584-ops-projects.vercel.app";

const GAS_CODE_SNIPPET = `/**
 * ---------------------------------------------------------
 * [VocaMaster 단어시험 채점 시스템]
 * 1. 이 코드를 복사해서 기존 내용을 모두 지우고 붙여넣으세요.
 * 2. 저장(디스켓 아이콘) 후 [배포] > [새 배포]를 누르세요.
 * 3. 톱니바퀴 > [웹 앱] 선택
 * 4. 설명: VocaMaster (입력 안 해도 됨)
 * 5. 액세스 권한: "모든 사용자" (★중요! 꼭 '모든 사용자'여야 합니다★)
 * 6. [배포] 클릭 -> [승인] -> URL 복사
 * ---------------------------------------------------------
 */

function doGet(e) {
  return ContentService.createTextOutput("VocaMaster 연결 성공! (설정이 완료되었습니다)");
}

function doPost(e) {
  if (typeof e === 'undefined' || !e.postData) {
    return ContentService.createTextOutput("⚠️ 이 함수는 직접 실행하는 것이 아닙니다. 웹 앱으로 배포 후 학생이 제출하면 자동으로 실행됩니다.");
  }

  try {
    var data = JSON.parse(e.postData.contents);
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheetName = data.tabName || "전체결과"; 
    var sheet = ss.getSheetByName(sheetName);

    if (!sheet) {
      sheet = ss.insertSheet(sheetName);
      sheet.appendRow(["이름", "점수", "총점", "소요시간(초)", "시험날짜", "제출일시"]);
    }

    sheet.appendRow([
      data.studentName,
      data.score,
      data.total,
      data.timeTaken,
      data.testDate,
      data.timestamp
    ]);

    return ContentService.createTextOutput("Success").setMimeType(ContentService.MimeType.TEXT);
  } catch(error) {
    return ContentService.createTextOutput("Error: " + error.toString()).setMimeType(ContentService.MimeType.TEXT);
  }
}`;

const sanitizeInput = (val: string) => {
  if (!val) return '';
  let clean = val.trim();
  clean = clean.replace(/\\$/, ''); 
  clean = clean.replace(/^"|"$/g, '');
  return clean;
};

const extractSheetId = (val: string) => {
  if (!val) return '';
  const match = val.match(/\/d\/([a-zA-Z0-9-_]+)/);
  return match ? match[1] : val;
};

const TeacherDashboard: React.FC = () => {
  const [sheetId, setSheetId] = useState('');
  const [scriptUrl, setScriptUrl] = useState('');
  const [baseUrl, setBaseUrl] = useState('');
  const [availableTabs, setAvailableTabs] = useState<string[]>([]);
  const [selectedClass, setSelectedClass] = useState('');

  const [isRefreshing, setIsRefreshing] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState<'none' | 'success' | 'success_manual' | 'fail'>('none');
  const [isCopied, setIsCopied] = useState(false);

  const [showScriptGuide, setShowScriptGuide] = useState(false);
  const [isCodeCopied, setIsCodeCopied] = useState(false);
  const [autoCorrected, setAutoCorrected] = useState<string | null>(null);

  useEffect(() => {
    const storedSheetId = localStorage.getItem(SHEET_ID_KEY) || '';
    const storedScriptUrl = localStorage.getItem(SCRIPT_URL_KEY) || '';
    const storedBaseUrl = localStorage.getItem(BASE_URL_KEY) || '';

    setSheetId(storedSheetId);
    setScriptUrl(sanitizeInput(storedScriptUrl));

    if (storedSheetId && !storedScriptUrl) {
      setShowScriptGuide(true);
    }

    // Smart Base URL Logic
    if (storedBaseUrl) {
      setBaseUrl(sanitizeInput(storedBaseUrl));
    } else {
      const currentUrl = window.location.origin + window.location.pathname;
      if (currentUrl.includes('localhost') || currentUrl.includes('127.0.0.1')) {
        setBaseUrl(PRESET_DOMAIN);
      } else {
        setBaseUrl(currentUrl);
      }
    }

    if (storedSheetId) {
      loadTabs(storedSheetId);
    }
  }, []);

  const loadTabs = async (id: string) => {
    if (!id) return;
    setIsRefreshing(true);
    try {
      const tabs = await fetchSheetTabs(id);
      if (tabs.length > 0) {
        setAvailableTabs(tabs);
        setConnectionStatus('success');
      } else {
        const isAvailable = await checkSheetAvailability(id);
        if (isAvailable) {
           setConnectionStatus('success_manual');
           setAvailableTabs([]);
        } else {
           setConnectionStatus('fail');
        }
      }
    } catch (e) { 
      console.error("Tabs loading error", e);
      setConnectionStatus('fail');
    } finally {
      setIsRefreshing(false);
    }
  };

  const handleSheetIdChange = (val: string) => {
    const extracted = extractSheetId(val);
    setSheetId(extracted);
    localStorage.setItem(SHEET_ID_KEY, extracted);
    setConnectionStatus('none');
  };

  const handleScriptUrlChange = (val: string) => {
    const clean = sanitizeInput(val);
    if (clean !== val.trim()) {
      setAutoCorrected('Apps Script 주소의 오타를 자동으로 수정했습니다.');
      setTimeout(() => setAutoCorrected(null), 3000);
    }
    setScriptUrl(clean);
    localStorage.setItem(SCRIPT_URL_KEY, clean);
  };

  const handleBaseUrlChange = (val: string) => {
    const clean = sanitizeInput(val);
    setBaseUrl(clean);
    localStorage.setItem(BASE_URL_KEY, clean);
  };

  const handleCopyCode = () => {
    navigator.clipboard.writeText(GAS_CODE_SNIPPET);
    setIsCodeCopied(true);
    setTimeout(() => setIsCodeCopied(false), 2000);
  };

  const shareUrl = useMemo(() => {
    if (!sheetId) return "";
    const params = new URLSearchParams();
    params.set('sheet_id', sheetId.trim());
    if (scriptUrl) params.set('script', scriptUrl.trim());
    if (selectedClass) params.set('class_name', selectedClass);
    params.set('date', new Date().toISOString().split('T')[0]);

    // URL Construction Logic (Robust)
    let url = baseUrl.trim();

    if (!url) {
        const current = window.location.origin + window.location.pathname;
        url = current.includes('localhost') ? PRESET_DOMAIN : current;
    }

    url = url.replace(/\/$/, '');

    if (!/^https?:\/\//i.test(url)) {
        if (url.includes('localhost') || url.includes('127.0.0.1')) {
            url = `http://${url}`;
        } else {
            url = `https://${url}`;
        }
    }

    return `${url}/?${params.toString()}`;
  }, [sheetId, scriptUrl, selectedClass, baseUrl]);

  const qrUrl = useMemo(() => {
    if (!shareUrl) return "";
    return `https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=${encodeURIComponent(shareUrl)}`;
