                   className={`w-full text-xs border rounded-lg p-3 font-mono break-all ${!shareUrl ? 'bg-orange-50 text-orange-600 border-orange-200' : 'bg-gray-50 text-gray-500 border-gray-200'}`}
                 />
              </div>

              <div className="flex gap-2">
                <Button 
                    variant="secondary" 
