          ) : (
            <>
              {!isUrlInitialized ? (
                <div className="animate-pop" style={{ animationDelay: '0.1s' }}>
                  <label className="block text-xs font-black text-indigo-500 uppercase tracking-widest mb-1">Step 01. 수업반 선택</label>
