        {/* 2-3. 배포 주소 설정 */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 transition-all hover:shadow-md ring-2 ring-indigo-50">
           <div className="flex justify-between items-start mb-4">
             <div>
