import { fetchWordsFromSheet, submitResultToSheet } from './services/sheetService';
import { APP_CONFIG } from './config';

const RESULT_STORAGE_KEY = 'vocamaster_results';
const INCORRECT_STORAGE_KEY = 'vocamaster_incorrect_notes';
const SHEET_ID_KEY = 'vocamaster_sheet_id';
const SCRIPT_URL_KEY = 'vocamaster_script_url';

function App() {
  const [currentView, setCurrentView] = useState<AppView>(AppView.LANDING);
  const [session, setSession] = useState<UserSession | null>(null);
  const [questions, setQuestions] = useState<Question[]>([]);
  const [lastResult, setLastResult] = useState<QuizResult | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [loadingMessage, setLoadingMessage] = useState('');
  const [submissionStatus, setSubmissionStatus] = useState<'idle' | 'submitting' | 'success' | 'error'>('idle');

  const [isReviewMode, setIsReviewMode] = useState(false);
  const [incorrectRecords, setIncorrectRecords] = useState<Record<string, IncorrectWord[]>>({});

  const [accessCode, setAccessCode] = useState('');
  const [loginError, setLoginError] = useState('');

  useEffect(() => {
    const stored = localStorage.getItem(INCORRECT_STORAGE_KEY);
    if (stored) {
      try { setIncorrectRecords(JSON.parse(stored)); } catch (e) {}
    }
  }, []);

  const saveResult = (result: QuizResult) => {
    const existing = localStorage.getItem(RESULT_STORAGE_KEY);
    const results: QuizResult[] = existing ? JSON.parse(existing) : [];
    results.push(result);
    localStorage.setItem(RESULT_STORAGE_KEY, JSON.stringify(results));
    setLastResult(result);

    const scriptUrl = localStorage.getItem(SCRIPT_URL_KEY) || APP_CONFIG.scriptUrl;
    if (scriptUrl) {
      setSubmissionStatus('submitting');
      submitResultToSheet(scriptUrl, result).then(success => setSubmissionStatus(success ? 'success' : 'error'));
    }
  };

  const updateIncorrectWords = (studentName: string, quizQuestions: Question[], wrongQuestions: Question[]) => {
    const records = { ...incorrectRecords };
    let studentKey = Object.keys(records).find(k => k.toLowerCase() === studentName.toLowerCase().trim()) || studentName.trim();
    if (!records[studentKey]) records[studentKey] = [];
    const studentWords = records[studentKey];
    const now = new Date().toISOString();

    if (isReviewMode) {
      const wrongIds = new Set(wrongQuestions.map(q => q.id));
      const correctIds = quizQuestions.filter(q => !wrongIds.has(q.id)).map(q => q.id);
      records[studentKey] = studentWords.map(w => {
         if (correctIds.includes(w.question.id)) return { ...w, wrongCount: Math.max(0, w.wrongCount - 1) };
         return w;
      }).filter(w => w.wrongCount > 0);
    } else {
      wrongQuestions.forEach(q => {
        const existingIndex = studentWords.findIndex(w => w.question.word === q.word);
        if (existingIndex >= 0) {
          studentWords[existingIndex].wrongCount += 1;
          studentWords[existingIndex].lastMissedDate = now;
        } else {
          studentWords.push({ question: q, wrongCount: 1, lastMissedDate: now });
        }
      });
    }
    setIncorrectRecords(records);
    localStorage.setItem(INCORRECT_STORAGE_KEY, JSON.stringify(records));
  };

  const handleStartQuiz = async (name: string, className: string, testDate: string, settings: QuizSettings) => {
    setSession({ name, className, testDate, settings });
    setIsLoading(true);
    setLoadingMessage(`단어 데이터를 불러오는 중...`);
    setIsReviewMode(false);

    try {
      const sheetId = localStorage.getItem(SHEET_ID_KEY) || APP_CONFIG.sheetId;
      if (!sheetId) throw new Error("시트 ID 설정이 필요합니다.");
      const sheetWords = await fetchWordsFromSheet(sheetId, className);
      setLoadingMessage(`시험지를 생성 중입니다...`);
      const generatedQuestions = await generateQuizQuestions(settings, sheetWords);
      setQuestions(generatedQuestions);
      setCurrentView(AppView.QUIZ);
    } catch (error: any) {
      alert(error.message);
      setSession(null);
    } finally {
      setIsLoading(false);
    }
  };

  const handleQuizComplete = (score: number, total: number, timeSeconds: number, wrongQuestions: Question[]) => {
    if (!session && !isReviewMode) return;
    const nameToUse = session?.name || "익명 학생";
    updateIncorrectWords(nameToUse, questions, wrongQuestions);
    const result: QuizResult = {
      studentName: nameToUse,
      className: session?.className || "복습",
      date: session?.testDate || new Date().toISOString().split('T')[0],
      score,
      totalQuestions: total,
      timeTakenSeconds: timeSeconds,
      timestamp: new Date().toISOString(),
    };
    if (!isReviewMode) saveResult(result);
    else setLastResult(result);
    setCurrentView(AppView.RESULT);
  };

  const handleLogout = () => { setSession(null); setQuestions([]); setLastResult(null); setIsReviewMode(false); setCurrentView(AppView.LANDING); };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 font-sans">
      <header className="bg-white shadow-sm border-b border-gray-200 sticky top-0 z-10">
        <div className="max-w-4xl mx-auto px-4 py-4 flex justify-between items-center">
          <div className="flex items-center gap-2 cursor-pointer" onClick={() => setCurrentView(AppView.LANDING)}>
            <div className="bg-indigo-600 text-white p-2 rounded-lg">
               <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M12 6.042A8.967 8.967 0 006 3.75c-1.052 0-2.062.18-3 .512v14.25A8.987 8.987 0 016 18c2.305 0 4.408.867 6 2.292m0-14.25a8.966 8.966 0 016-2.292c1.052 0 2.062.18 3 .512v14.25A8.987 8.987 0 0018 18a8.967 8.967 0 00-6 2.292m0-14.25v14.25" /></svg>
            </div>
            <h1 className="text-xl font-bold tracking-tight">PIF영어학원</h1>
          </div>
          {currentView === AppView.LANDING && (
            <button onClick={() => setCurrentView(AppView.TEACHER_LOGIN)} className="px-4 py-2 rounded-md bg-gray-100 text-sm font-medium">선생님</button>
          )}
          {(currentView === AppView.TEACHER_DASHBOARD || currentView === AppView.TEACHER_LOGIN) && (
            <button onClick={handleLogout} className="text-sm text-gray-500 font-medium">닫기</button>
          )}
        </div>
      </header>
      <main className="max-w-4xl mx-auto px-4 py-8">
        {isLoading ? (
          <div className="flex flex-col items-center justify-center h-96 animate-pop text-center">
             <div className="w-16 h-16 border-4 border-indigo-200 border-t-indigo-600 rounded-full animate-spin mb-6"></div>
             <p className="text-lg text-gray-600 font-semibold">{loadingMessage}</p>
          </div>
        ) : (
          <>
            {currentView === AppView.LANDING && <Landing onStart={handleStartQuiz} onChangeView={setCurrentView} />}
            {currentView === AppView.QUIZ && session && <Quiz questions={questions} settings={session.settings} onComplete={handleQuizComplete} />}
            {currentView === AppView.RESULT && lastResult && <Result result={lastResult} onHome={handleLogout} submissionStatus={submissionStatus} />}
            {currentView === AppView.TEACHER_LOGIN && (
              <div className="max-w-md mx-auto bg-white p-8 rounded-2xl shadow-lg border border-gray-100 animate-pop text-center">
                <h2 className="text-2xl font-bold mb-6">선생님 로그인</h2>
                <input type="password" value={accessCode} onChange={(e) => setAccessCode(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && (accessCode === 'teacher' ? setCurrentView(AppView.TEACHER_DASHBOARD) : setLoginError('Error'))} className="w-full px-4 py-2 border rounded-lg mb-4" placeholder="Password" />
                <button onClick={() => accessCode === 'teacher' ? setCurrentView(AppView.TEACHER_DASHBOARD) : setLoginError('Error')} className="w-full bg-indigo-600 text-white py-2 rounded-lg">Enter</button>
              </div>
            )}
            {currentView === AppView.TEACHER_DASHBOARD && <TeacherDashboard />}
          </>
        )}
      </main>
    </div>
  );
}
export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { Question, SheetWord, QuizSettings } from "../types";

// Helper to shuffle array (Fisher-Yates)
const shuffleArray = <T,>(array: T[]): T[] => {
  const newArray = [...array];
  for (let i = newArray.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [newArray[i], newArray[j]] = [newArray[j], newArray[i]];
  }
  return newArray;
};

/**
 * Generates a quiz locally using sheet words as distractors.
 * Fallback mechanism.
 */
const generateLocalQuiz = (sheetWords: SheetWord[], settings: QuizSettings): Question[] => {
  const total = Math.min(sheetWords.length, settings.totalQuestions);
  const shuffledSource = shuffleArray(sheetWords);
  const limitedWords = shuffledSource.slice(0, total);

  const allMeanings = sheetWords.map(sw => sw.meaning);
  const allWords = sheetWords.map(sw => sw.word);

  return limitedWords.map((sw, idx) => {
    let showWord = '';
    let correctAnswer = '';
    let distractorsPool: string[] = [];

    // Determine type for this specific question
    let currentType = settings.questionType;
    if (currentType === 'mixed') {
      currentType = idx < (total / 2) ? 'engToKor' : 'korToEng';
    }

    if (currentType === 'engToKor') {
      showWord = sw.word;
      correctAnswer = sw.meaning;
      distractorsPool = allMeanings.filter(m => m !== correctAnswer);
    } else {
      showWord = sw.meaning;
      correctAnswer = sw.word;
      distractorsPool = allWords.filter(w => w !== correctAnswer);
    }

    const distractors = shuffleArray(distractorsPool).slice(0, 3);
    const options = shuffleArray([correctAnswer, ...distractors]);

    return {
      id: idx,
      word: showWord,
      options,
      correctAnswerIndex: options.indexOf(correctAnswer)
    };
  });
};

export const generateQuizQuestions = async (settings: QuizSettings, sheetWords?: SheetWord[]): Promise<Question[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = "gemini-3-flash-preview";

  if (!sheetWords || sheetWords.length === 0) {
    throw new Error("시험을 생성할 단어 데이터가 없습니다.");
  }

  const shuffled = shuffleArray(sheetWords);
  const limitedWords = shuffled.slice(0, settings.totalQuestions); 

  const prompt = `
    I have a vocabulary list for a high-quality test. 
    SOURCE DATA: ${JSON.stringify(limitedWords)}

    Task: Create a test with exactly ${settings.totalQuestions} questions following strict pedagogical guidelines.

    QUIZ TYPE SETTING: ${settings.questionType}
    - If 'mixed': Split questions equally between (English Word -> Korean Meaning) and (Korean Meaning -> English Word).
    - If 'engToKor': Show English, ask for Korean meaning.
    - If 'korToEng': Show Korean, ask for English word.

    STRICT GUIDELINES FOR OPTIONS (DISTRACTORS):
    1. **PART OF SPEECH (품사 일치)**: All 4 options (correct answer and 3 distractors) MUST belong to the same part of speech (e.g., all verbs, all nouns, all adjectives).
    2. **NO SYNONYMS (의미 중복 금지)**: Do NOT use distractors that are synonyms or have overlapping/similar meanings to the correct answer. This is critical to prevent multiple correct answers. (e.g., if the answer is 'clear', do not use 'vivid' as a distractor).
    3. **BALANCED DIFFICULTY (난이도 조절)**: Distractors should be plausible but clearly incorrect. Do not make the correct answer too obvious by using irrelevant words.
    4. **NO AMBIGUITY**: Ensure the correct answer is the single most accurate translation based on the source data.
    5. **Shuffle**: Randomly place the correct answer among the 4 options and set 'correctAnswerIndex' (0-3) accurately.

    Return the result as a JSON array of Question objects.
  `;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.INTEGER },
              word: { type: Type.STRING },
              options: { 
                type: Type.ARRAY, 
                items: { type: Type.STRING },
              },
              correctAnswerIndex: { type: Type.INTEGER }
            },
            required: ["id", "word", "options", "correctAnswerIndex"],
          },
        },
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from Gemini");

    return JSON.parse(text) as Question[];

  } catch (error: any) {
    console.warn("Gemini API Error. Falling back to local generation:", error.message);
    return generateLocalQuiz(sheetWords, settings);
  }
};

import React, { useEffect, useState, useMemo } from 'react';
import Button from '../components/Button';
import { fetchSheetTabs, checkSheetAvailability } from '../services/sheetService';
import { APP_CONFIG } from '../config';
import { QuestionType } from '../types';

const SHEET_ID_KEY = 'vocamaster_sheet_id';
const SCRIPT_URL_KEY = 'vocamaster_script_url';
const BASE_URL_KEY = 'vocamaster_base_url';
const SETTINGS_KEY = 'vocamaster_quiz_settings';

const APP_VERSION = "v1.16 (Enhanced UI)";

const GAS_CODE_SNIPPET = `/**
 * [VocaMaster 단어시험 채점 시스템 v1.16]
 */
function doGet(e) { return ContentService.createTextOutput("VocaMaster 연결 성공!"); }
function doPost(e) {
  if (typeof e === 'undefined' || !e.postData) return ContentService.createTextOutput("⚠️ Error");
  try {
    var data = JSON.parse(e.postData.contents);
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheet = ss.getSheetByName("결과") || ss.insertSheet("결과");
    if (sheet.getLastRow() == 0) {
      sheet.appendRow(["구분(반)", "이름", "점수", "총점", "소요시간(초)", "시험날짜", "제출일시"]);
      sheet.setFrozenRows(1);
    }
    sheet.appendRow([data.tabName, data.studentName, data.score, data.total, data.timeTaken, data.testDate, data.timestamp]);
    return ContentService.createTextOutput("Success");
  } catch(e) { return ContentService.createTextOutput("Error: " + e.toString()); }
}`;

const TeacherDashboard: React.FC = () => {
  const [sheetId, setSheetId] = useState('');
  const [scriptUrl, setScriptUrl] = useState('');
  const [baseUrl, setBaseUrl] = useState('');

  // Quiz Settings
  const [totalQuestions, setTotalQuestions] = useState(APP_CONFIG.defaultSettings.totalQuestions);
  const [timeLimit, setTimeLimit] = useState(APP_CONFIG.defaultSettings.timeLimitPerQuestion);
  const [questionType, setQuestionType] = useState<QuestionType>(APP_CONFIG.defaultSettings.questionType);

  const [availableTabs, setAvailableTabs] = useState<string[]>([]);
  const [selectedClass, setSelectedClass] = useState('');
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState<'none' | 'success' | 'success_manual' | 'fail'>('none');
  const [isCopied, setIsCopied] = useState(false);
  const [showScriptGuide, setShowScriptGuide] = useState(false);
  const [isCodeCopied, setIsCodeCopied] = useState(false);

  useEffect(() => {
    setSheetId(localStorage.getItem(SHEET_ID_KEY) || APP_CONFIG.sheetId);
    setScriptUrl(localStorage.getItem(SCRIPT_URL_KEY) || APP_CONFIG.scriptUrl);
    setBaseUrl(localStorage.getItem(BASE_URL_KEY) || APP_CONFIG.baseUrl || "");

    const savedSettings = localStorage.getItem(SETTINGS_KEY);
    if (savedSettings) {
      const parsed = JSON.parse(savedSettings);
      setTotalQuestions(parsed.totalQuestions);
      setTimeLimit(parsed.timeLimitPerQuestion);
      setQuestionType(parsed.questionType);
    }

    if (localStorage.getItem(SHEET_ID_KEY) || APP_CONFIG.sheetId) {
      loadTabs(localStorage.getItem(SHEET_ID_KEY) || APP_CONFIG.sheetId);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify({
      totalQuestions,
      timeLimitPerQuestion: timeLimit,
      questionType
    }));
  }, [totalQuestions, timeLimit, questionType]);

  const loadTabs = async (id: string) => {
    if (!id) return;
    setIsRefreshing(true);
    try {
      const tabs = await fetchSheetTabs(id);
      if (tabs.length > 0) {
        setAvailableTabs(tabs);
        setConnectionStatus('success');
      } else {
        const isAvailable = await checkSheetAvailability(id);
        setConnectionStatus(isAvailable ? 'success_manual' : 'fail');
      }
    } catch (e) {
      setConnectionStatus('fail');
    } finally {
      setIsRefreshing(false);
    }
  };

  const shareUrl = useMemo(() => {
    if (!sheetId) return "";
    const params = new URLSearchParams();
    params.set('sheet_id', sheetId.trim());
    if (scriptUrl) params.set('script', scriptUrl.trim());
    if (selectedClass) params.set('class_name', selectedClass);
    params.set('num_q', totalQuestions.toString());
    params.set('t_limit', timeLimit.toString());
    params.set('q_type', questionType);
    params.set('date', new Date().toISOString().split('T')[0]);

    let url = baseUrl.trim() || window.location.origin + window.location.pathname;
    url = url.replace(/\/$/, '');
    if (!/^https?:\/\//i.test(url)) url = `https://${url}`;

    return `${url}/?${params.toString()}`;
  }, [sheetId, scriptUrl, selectedClass, baseUrl, totalQuestions, timeLimit, questionType]);

  const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=${encodeURIComponent(shareUrl)}`;

  return (
    <div className="animate-pop space-y-8 pb-24">
      <div className="text-center space-y-2">
        <h2 className="text-3xl font-black text-gray-900 tracking-tight">선생님 관리 대시보드</h2>
        <p className="text-gray-500 text-sm">학생들에게 배포할 시험 링크를 생성하고 시스템을 설정합니다.</p>
      </div>

      {/* 1. 시험 커스터마이징 */}
      <section className="bg-white rounded-[2rem] shadow-xl overflow-hidden border border-gray-100">
        <div className="bg-indigo-600 px-8 py-5 text-white flex justify-between items-center">
          <h3 className="font-bold text-lg">시험 문제 및 설정</h3>
          <span className="text-xs font-bold bg-white/20 px-2 py-1 rounded">Step 1</span>
        </div>
        <div className="p-8 grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="space-y-2">
            <label className="text-sm font-bold text-gray-700">문항 수</label>
            <input 
              type="number" 
              value={totalQuestions} 
              onChange={(e) => setTotalQuestions(Number(e.target.value))}
              className="w-full px-4 py-3 bg-gray-50 border-2 border-gray-100 rounded-xl focus:border-indigo-500 outline-none font-bold"
            />
          </div>
          <div className="space-y-2">
            <label className="text-sm font-bold text-gray-700">문항당 시간 제한 (초)</label>
            <div className="relative">
              <input 
                type="number" 
                value={timeLimit} 
                onChange={(e) => setTimeLimit(Number(e.target.value))}
                className="w-full px-4 py-3 bg-gray-50 border-2 border-gray-100 rounded-xl focus:border-indigo-500 outline-none font-bold"
                placeholder="0 = 무제한"
              />
              <span className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 font-bold">초</span>
            </div>
          </div>
          <div className="space-y-2">
            <label className="text-sm font-bold text-gray-700">문제 유형</label>
            <select 
              value={questionType} 
              onChange={(e) => setQuestionType(e.target.value as QuestionType)}
              className="w-full px-4 py-3 bg-gray-50 border-2 border-gray-100 rounded-xl focus:border-indigo-500 outline-none font-bold appearance-none"
            >
              <option value="mixed">영어/한글 혼합</option>
              <option value="engToKor">영어 보고 뜻 고르기</option>
              <option value="korToEng">한글 보고 영어 고르기</option>
            </select>
          </div>
        </div>
      </section>

      {/* 2. QR 배포 섹션 */}
      <section className="bg-white rounded-[2rem] shadow-xl overflow-hidden border border-gray-100">
        <div className="bg-gray-900 px-8 py-5 text-white flex justify-between items-center">
          <h3 className="font-bold text-lg">시험 배포 (QR & 링크)</h3>
          <span className="text-xs font-bold bg-white/10 px-2 py-1 rounded">Step 2</span>
        </div>
        <div className="p-8 grid grid-cols-1 md:grid-cols-2 gap-8 items-center">
          <div className="space-y-6">
            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase mb-2">1. 배포할 수업반 선택</label>
              {availableTabs.length > 0 ? (
                <select value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)} className="w-full px-4 py-4 border-2 border-indigo-100 rounded-xl font-bold text-gray-700 bg-indigo-50/30 outline-none">
                  <option value="">-- 반 선택 --</option>
                  {availableTabs.map(t => <option key={t} value={t}>{t}</option>)}
                </select>
              ) : (
                <input type="text" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)} placeholder="탭 이름을 입력하세요" className="w-full px-4 py-4 border-2 border-indigo-100 rounded-xl font-bold" />
              )}
            </div>
            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase mb-2">2. 링크 공유 및 확인</label>
              <div className="flex flex-col gap-2">
                <input readOnly value={shareUrl} className="w-full text-xs border rounded-lg p-3 font-mono bg-gray-50 mb-1" />
                <div className="flex gap-2">
                  <Button 
                    fullWidth 
                    variant="primary" 
                    onClick={() => { 
                      navigator.clipboard.writeText(shareUrl); 
                      setIsCopied(true); 
                      setTimeout(() => setIsCopied(false), 2000); 
                    }}
                  >
                    {isCopied ? '✅ 복사됨' : '🔗 링크 복사'}
                  </Button>
                  <a 
                    href={shareUrl} 
                    target="_blank" 
                    rel="noopener noreferrer"
                    className="flex-1 bg-indigo-50 text-indigo-700 border border-indigo-200 px-4 py-2 rounded-lg font-bold flex items-center justify-center hover:bg-indigo-100 transition-colors"
                  >
                    🌐 열기
                  </a>
                </div>
              </div>
            </div>
          </div>
          <div className="flex flex-col items-center justify-center p-6 bg-gray-50 rounded-3xl border-2 border-dashed border-gray-200">
            {selectedClass && shareUrl ? (
              <img src={qrUrl} alt="QR" className="w-40 h-40 mix-blend-multiply" />
            ) : (
              <div className="text-gray-300 text-xs font-bold text-center py-10">반을 선택하면<br/>QR이 생성됩니다</div>
            )}
          </div>
        </div>
      </section>

      {/* 3. 시스템 설정 */}
      <section className="space-y-4">
        <h3 className="text-lg font-black text-gray-800 px-2">⚙️ 시스템 연동 설정</h3>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 space-y-4">
