function App() {
  const [currentView, setCurrentView] = useState<AppView>(AppView.LANDING);
  const [session, setSession] = useState<UserSession | null>(null);

  // Data State
  const [questions, setQuestions] = useState<Question[]>([]); // For Quiz Mode
  const [rawPracticeWords, setRawPracticeWords] = useState<SheetWord[]>([]); // For Practice Mode (Full List)
  const [activePracticeSet, setActivePracticeSet] = useState<SheetWord[]>([]); // For Flashcard Mode (Selected Set)
  const [activeSetTitle, setActiveSetTitle] = useState('');

  const [lastResult, setLastResult] = useState<QuizResult | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [loadingMessage, setLoadingMessage] = useState('');
  const [submissionStatus, setSubmissionStatus] = useState<'idle' | 'submitting' | 'success' | 'error'>('idle');

  const [isReviewMode, setIsReviewMode] = useState(false);
  const [incorrectRecords, setIncorrectRecords] = useState<Record<string, IncorrectWord[]>>({});

  const [accessCode, setAccessCode] = useState('');
  const [loginError, setLoginError] = useState('');

  useEffect(() => {
    const stored = localStorage.getItem(INCORRECT_STORAGE_KEY);
    if (stored) {
      try { setIncorrectRecords(JSON.parse(stored)); } catch (e) {}
    }
  }, []);

  const saveResult = (result: QuizResult) => {
    // Only save to local storage and google sheet if it is TEST mode
    if (result.mode === 'TEST') {
      const existing = localStorage.getItem(RESULT_STORAGE_KEY);
      const results: QuizResult[] = existing ? JSON.parse(existing) : [];
      results.push(result);
      localStorage.setItem(RESULT_STORAGE_KEY, JSON.stringify(results));
    }

    setLastResult(result);

    // Submission logic
    if (result.mode === 'TEST') {
      const scriptUrl = localStorage.getItem(SCRIPT_URL_KEY) || APP_CONFIG.scriptUrl;
      if (scriptUrl) {
        setSubmissionStatus('submitting');
        submitResultToSheet(scriptUrl, result).then(success => setSubmissionStatus(success ? 'success' : 'error'));
      }
    } else {
      setSubmissionStatus('idle');
    }
  };

  const updateIncorrectWords = (studentName: string, quizQuestions: Question[], wrongQuestions: Question[]) => {
    const records = { ...incorrectRecords };
    let studentKey = Object.keys(records).find(k => k.toLowerCase() === studentName.toLowerCase().trim()) || studentName.trim();
    if (!records[studentKey]) records[studentKey] = [];
    const studentWords = records[studentKey];
    const now = new Date().toISOString();

    if (isReviewMode) {
      const wrongIds = new Set(wrongQuestions.map(q => q.id));
      const correctIds = quizQuestions.filter(q => !wrongIds.has(q.id)).map(q => q.id);
      records[studentKey] = studentWords.map(w => {
         if (correctIds.includes(w.question.id)) return { ...w, wrongCount: Math.max(0, w.wrongCount - 1) };
         return w;
      }).filter(w => w.wrongCount > 0);
    } else {
      wrongQuestions.forEach(q => {
        const existingIndex = studentWords.findIndex(w => w.question.word === q.word);
        if (existingIndex >= 0) {
          studentWords[existingIndex].wrongCount += 1;
          studentWords[existingIndex].lastMissedDate = now;
        } else {
          studentWords.push({ question: q, wrongCount: 1, lastMissedDate: now });
        }
      });
    }
    setIncorrectRecords(records);
    localStorage.setItem(INCORRECT_STORAGE_KEY, JSON.stringify(records));
  };

  const handleStartQuiz = async (name: string, className: string, testDate: string, settings: QuizSettings, mode: 'TEST' | 'PRACTICE') => {
    setSession({ name, className, testDate, settings, mode });
    setIsLoading(true);
    setLoadingMessage(`단어 데이터를 불러오는 중...`);
    setIsReviewMode(false);

    try {
      const sheetId = localStorage.getItem(SHEET_ID_KEY) || APP_CONFIG.sheetId;
      if (!sheetId) throw new Error("시트 ID 설정이 필요합니다.");

      const sheetWords = await fetchWordsFromSheet(sheetId, className);

      if (mode === 'PRACTICE') {
        // PRACTICE MODE: Store raw words and go to selection screen
        setRawPracticeWords(sheetWords);
        setIsLoading(false);
        setCurrentView(AppView.PRACTICE_SELECT);
      } else {
        // TEST MODE: Generate Questions
        setLoadingMessage('시험지를 생성 중입니다...');
        const generatedQuestions = await generateQuizQuestions(settings, sheetWords, false);
        setQuestions(generatedQuestions);
        setIsLoading(false);
        setCurrentView(AppView.QUIZ);
      }
    } catch (error: any) {
      alert(error.message);
      setSession(null);
      setIsLoading(false);
    }
  };

  const handlePracticeSetSelect = (words: SheetWord[], setIndex: number) => {
    setActivePracticeSet(words);
    setActiveSetTitle(`SET ${setIndex} 연습`);
    setCurrentView(AppView.FLASHCARD);
  };

  const handleQuizComplete = (score: number, total: number, timeSeconds: number, wrongQuestions: Question[]) => {
    if (!session && !isReviewMode) return;
    const nameToUse = session?.name || "익명 학생";

    updateIncorrectWords(nameToUse, questions, wrongQuestions);

    const result: QuizResult = {
      studentName: nameToUse,
      className: session?.className || "복습",
      date: session?.testDate || new Date().toISOString().split('T')[0],
      score,
      totalQuestions: total,
      timeTakenSeconds: timeSeconds,
      timestamp: new Date().toISOString(),
      incorrectQuestions: wrongQuestions,
      mode: session?.mode || 'TEST'
    };

    if (!isReviewMode) saveResult(result);
    else setLastResult(result);

    setCurrentView(AppView.RESULT);
  };

  const handleLogout = () => { 
    setSession(null); 
    setQuestions([]); 
    setLastResult(null); 
    setIsReviewMode(false); 
    setCurrentView(AppView.LANDING); 
  };

  const renderCurrentView = () => {
    switch (currentView) {
      case AppView.LANDING:
        return <Landing onStart={handleStartQuiz} onChangeView={setCurrentView} />;
      case AppView.QUIZ:
        return session && <Quiz questions={questions} settings={session.settings} onComplete={handleQuizComplete} />;
      case AppView.RESULT:
        return lastResult && <Result result={lastResult} onHome={handleLogout} submissionStatus={submissionStatus} />;
      case AppView.TEACHER_LOGIN:
        return (
          <div className="max-w-md mx-auto bg-white p-8 rounded-2xl shadow-lg border border-gray-100 animate-pop text-center">
            <h2 className="text-2xl font-bold mb-6">선생님 로그인</h2>
            <input type="password" value={accessCode} onChange={(e) => setAccessCode(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && (accessCode === 'teacher' ? setCurrentView(AppView.TEACHER_DASHBOARD) : setLoginError('Error'))} className="w-full px-4 py-2 border rounded-lg mb-4" placeholder="Password" />
            <button onClick={() => accessCode === 'teacher' ? setCurrentView(AppView.TEACHER_DASHBOARD) : setLoginError('Error')} className="w-full bg-indigo-600 text-white py-2 rounded-lg">Enter</button>
          </div>
        );
      case AppView.TEACHER_DASHBOARD:
        return <TeacherDashboard />;
      case AppView.PRACTICE_SELECT:
        return <PracticeSelect totalWords={rawPracticeWords} onSelectSet={handlePracticeSetSelect} onBack={handleLogout} />;
      case AppView.FLASHCARD:
        return <FlashcardStudy words={activePracticeSet} setTitle={activeSetTitle} onFinish={() => setCurrentView(AppView.PRACTICE_SELECT)} />;
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 font-sans">
      <header className="bg-white shadow-sm border-b border-gray-200 sticky top-0 z-10">
        <div className="max-w-4xl mx-auto px-4 py-4 flex justify-between items-center">
          <div className="flex items-center gap-2 cursor-pointer" onClick={() => setCurrentView(AppView.LANDING)}>
            <div className="bg-indigo-600 text-white p-2 rounded-lg">
               <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M12 6.042A8.967 8.967 0 006 3.75c-1.052 0-2.062.18-3 .512v14.25A8.987 8.987 0 016 18c2.305 0 4.408.867 6 2.292m0-14.25a8.966 8.966 0 016-2.292c1.052 0 2.062.18 3 .512v14.25A8.987 8.987 0 0018 18a8.967 8.967 0 00-6 2.292m0-14.25v14.25" /></svg>
            </div>
            <h1 className="text-xl font-bold tracking-tight">PIF영어학원</h1>
            {session?.mode === 'PRACTICE' && (
              <span className="bg-green-100 text-green-700 text-xs px-2 py-1 rounded-full font-bold ml-2">연습모드</span>
            )}
          </div>
          {currentView === AppView.LANDING && (
            <button onClick={() => setCurrentView(AppView.TEACHER_LOGIN)} className="px-4 py-2 rounded-md bg-gray-100 text-sm font-medium">선생님</button>
          )}
          {(currentView !== AppView.LANDING) && (
            <button onClick={handleLogout} className="text-sm text-gray-500 font-medium">닫기</button>
          )}
        </div>
      </header>
      <main className="max-w-4xl mx-auto px-4 py-8">
        {isLoading ? (
          <div className="flex flex-col items-center justify-center h-96 animate-pop text-center">
             <div className="w-16 h-16 border-4 border-indigo-200 border-t-indigo-600 rounded-full animate-spin mb-6"></div>
             <p className="text-lg text-gray-600 font-semibold">{loadingMessage}</p>
          </div>
        ) : (
          renderCurrentView()
        )}
      </main>
    </div>
  );
}
export default App;

import React, { useState, useEffect } from 'react';
import { SheetWord } from '../types';
import Button from '../components/Button';

interface FlashcardStudyProps {
  words: SheetWord[];
  setTitle: string;
  onFinish: () => void;
}

const FlashcardStudy: React.FC<FlashcardStudyProps> = ({ words, setTitle, onFinish }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isFlipped, setIsFlipped] = useState(false);
  const [shuffledWords, setShuffledWords] = useState<SheetWord[]>([]);
  const [isShuffled, setIsShuffled] = useState(false);

  useEffect(() => {
    setShuffledWords([...words]);
  }, [words]);

  const handleShuffle = () => {
    const newOrder = [...words];
    for (let i = newOrder.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [newOrder[i], newOrder[j]] = [newOrder[j], newOrder[i]];
    }
    setShuffledWords(newOrder);
    setIsShuffled(true);
    setCurrentIndex(0);
    setIsFlipped(false);
  };

  const handleNext = () => {
    if (currentIndex < shuffledWords.length - 1) {
      setIsFlipped(false);
      // Small delay to allow the flip animation to reset visually if needed, 
      // though we want it instant for 'next card' feel.
      setTimeout(() => setCurrentIndex(prev => prev + 1), 150);
    }
  };

  const handlePrev = () => {
    if (currentIndex > 0) {
      setIsFlipped(false);
      setTimeout(() => setCurrentIndex(prev => prev - 1), 150);
    }
  };

  const handleCardClick = () => {
    if (!isFlipped) {
      // If showing front, flip to back
      setIsFlipped(true);
    } else {
      // If showing back (meaning), go to next card
      if (currentIndex < shuffledWords.length - 1) {
        handleNext();
      } else {
        // Optional: If it's the last card, maybe just flip back or do nothing
        // For now, let's just flip back so they can see English again if they want
        setIsFlipped(false);
      }
    }
  };

  if (shuffledWords.length === 0) return null;

  const currentWord = shuffledWords[currentIndex];
  const progress = ((currentIndex + 1) / shuffledWords.length) * 100;

  return (
    <div className="max-w-md mx-auto h-full flex flex-col animate-pop">
      {/* Header Info */}
      <div className="flex justify-between items-center mb-4 px-2">
        <div>
          <h2 className="text-lg font-bold text-gray-800">{setTitle}</h2>
          <p className="text-xs text-gray-500 font-medium">
             {isShuffled ? '🔀 순서 섞임' : '🔢 기본 순서'}
          </p>
        </div>
        <div className="text-right">
          <span className="text-xl font-black text-indigo-600">{currentIndex + 1}</span>
          <span className="text-sm font-medium text-gray-400"> / {shuffledWords.length}</span>
        </div>
      </div>

      {/* Progress Bar */}
      <div className="w-full bg-gray-200 rounded-full h-1.5 mb-6">
        <div className="bg-indigo-600 h-1.5 rounded-full transition-all duration-300" style={{ width: `${progress}%` }}></div>
      </div>

      {/* Flashcard Area */}
      <div className="flex-1 relative perspective-1000 min-h-[400px] mb-8 group cursor-pointer" onClick={handleCardClick}>
        <div className={`relative w-full h-full transition-transform duration-500 transform-style-3d ${isFlipped ? 'rotate-y-180' : ''}`}>

          {/* FRONT (English) */}
          <div className="absolute w-full h-full backface-hidden bg-white rounded-3xl shadow-xl border-2 border-indigo-50 flex flex-col p-6">
             <div className="h-12 flex items-center justify-center">
                <span className="text-xs font-black text-indigo-300 uppercase tracking-widest">English</span>
             </div>

             <div className="flex-1 flex items-center justify-center w-full overflow-hidden">
                <h3 className="text-3xl md:text-4xl font-black text-gray-800 break-words text-center px-4 leading-tight">
                  {currentWord.word}
                </h3>
             </div>

             <div className="h-12 flex items-center justify-center">
                <p className="text-xs text-gray-400 font-medium animate-pulse">터치해서 뜻 확인하기</p>
             </div>
          </div>

          {/* BACK (Meaning) */}
          <div className="absolute w-full h-full backface-hidden rotate-y-180 bg-indigo-600 rounded-3xl shadow-xl flex flex-col p-6 text-white">
             <div className="h-12 flex items-center justify-center">
                <span className="text-xs font-black text-indigo-300 uppercase tracking-widest">Meaning</span>
             </div>

             <div className="flex-1 flex items-center justify-center w-full overflow-hidden">
                <h3 className="text-2xl md:text-3xl font-bold break-keep text-center px-4 leading-snug">
                  {currentWord.meaning}
                </h3>
             </div>

             <div className="h-12 flex items-center justify-center">
               {currentIndex < shuffledWords.length - 1 ? (
                 <p className="text-xs text-indigo-200 font-medium animate-pulse">터치해서 다음 단어</p>
               ) : (
                 <p className="text-xs text-indigo-200 font-medium">마지막 단어입니다</p>
               )}
             </div>
          </div>

        </div>
      </div>

      {/* Controls */}
      <div className="grid grid-cols-2 gap-4 mb-4">
        <Button 
          onClick={(e) => { e.stopPropagation(); handlePrev(); }} 
          disabled={currentIndex === 0}
          variant="secondary"
          className="rounded-xl h-14 text-lg font-bold"
        >
          ← 이전
        </Button>
        <Button 
          onClick={(e) => { e.stopPropagation(); handleNext(); }} 
          disabled={currentIndex === shuffledWords.length - 1}
          variant="primary"
          className="rounded-xl h-14 text-lg font-bold"
        >
          다음 →
        </Button>
      </div>

      <div className="flex justify-between gap-4">
         <button onClick={handleShuffle} className="text-xs font-bold text-gray-500 py-3 px-4 rounded-xl bg-gray-100 hover:bg-gray-200 transition-colors flex-1">
           🔀 순서 섞기
         </button>
         <button onClick={onFinish} className="text-xs font-bold text-gray-500 py-3 px-4 rounded-xl bg-gray-100 hover:bg-gray-200 transition-colors flex-1">
           🚪 목록으로
         </button>
      </div>

    </div>
  );
};

