      </div>
    );
  }

  // --- RENDER: STUDY MODE ---
  const currentWord = currentQueue[currentIndex];
  const progress = ((currentIndex + 1) / currentQueue.length) * 100;
  const isMarked = markedWords.has(currentWord?.word);

